import React, { useState } from 'react'
import { AppSidebar } from "./Sidebar"
import { SiteHeader } from "./Header"
import { SidebarInset, SidebarProvider } from "@/components/ui/sidebar"
import { ScrollArea } from "@/components/ui/scroll-area"
import { Outlet } from "react-router-dom"
import AiInput from "@/components/ai-input"
import { authHeaders } from "@/lib/api"

const AdminLayout = () => {
  const [aiMessages, setAiMessages] = useState([])
  const [aiLoading, setAiLoading] = useState(false)

  const handleSendAi = async (prompt) => {
    const userMsg = { role: 'user', content: prompt }
    setAiMessages((prev) => [...prev, userMsg])
    setAiLoading(true)

    try {
      const apiUrl = import.meta.env.VITE_API_URL || '/api'
      const res = await fetch(`${apiUrl}/ai/chat`, {
        method: 'POST',
        credentials: 'include',
        headers: { ...authHeaders(), 'Content-Type': 'application/json' },
        body: JSON.stringify({ prompt, history: aiMessages })
      }).catch(() => null)

      let reply = ""
      if (res && res.ok) {
        const data = await res.json().catch(() => ({}))
        reply = data.response || data.message || data.reply
      }

      if (!reply) {
        const p = prompt.toLowerCase()
        if (p.includes("company") || p.includes("companies")) {
          reply = "You can view and manage all registered entities in **Company Registered** (`/admin/companies`)."
        } else if (p.includes("account") || p.includes("filing") || p.includes("tax") || p.includes("hmrc")) {
          reply = "The **Accountancy** module (`/admin/accountancy`) manages Companies House annual accounts and HMRC returns."
        } else if (p.includes("customer") || p.includes("client") || p.includes("b2b")) {
          reply = "All B2B accounts and website signups are in **Customers & Signups** (`/admin/customers`)."
        } else {
          reply = `I've noted your request: **"${prompt}"**. I can assist with company filings, CRM customers, orders, and accountancy.`
        }
      }

      setAiMessages((prev) => [...prev, { role: 'assistant', content: reply }])
    } catch {
      setAiMessages((prev) => [...prev, { role: 'assistant', content: "I encountered an issue processing your request. Please try again." }])
    } finally {
      setAiLoading(false)
    }
  }

  return (
    <SidebarProvider>
      <AppSidebar />
      <SidebarInset className="p-2 bg-sidebar h-svh overflow-hidden relative">
        <ScrollArea className="h-full w-full rounded-xl border bg-background shadow-sm">
          <SiteHeader />
          <main className="flex flex-col gap-4 p-2 lg:p-6 pb-20">
            <Outlet />
          </main>
        </ScrollArea>

        <AiInput
          messages={aiMessages}
          loading={aiLoading}
          onSubmit={handleSendAi}
        />
      </SidebarInset>
    </SidebarProvider>
  )
}

export default AdminLayout

"use client"

import React from "react"
import { Bar, BarChart, CartesianGrid, XAxis, YAxis, Area, AreaChart, LabelList, Pie, PieChart } from "recharts"

import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
} from "@/components/ui/chart"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectGroup,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Skeleton } from "@/components/ui/skeleton"

const barChartConfig = {
  revenue: {
    label: "Sales Revenue",
    color: "var(--chart-3)",
  },
}

export function ChartBarMultiple({
  data = [],
  timeFilter = "This Year",
  onTimeFilterChange,
  isLoading = false,
}) {
  if (isLoading) {
    return <Skeleton className="w-full h-[360px] rounded-xl" />
  }

  const displayData = data && data.length > 0 ? data : []

  return (
    <Card className="flex flex-col chart-revenue-privacy relative">
      <CardHeader className="flex flex-row items-center justify-between pb-2">
        <div className="space-y-1">
          <CardTitle>Sales Revenue</CardTitle>
        </div>
        {onTimeFilterChange && (
          <Select value={timeFilter} onValueChange={onTimeFilterChange}>
            <SelectTrigger className="w-[120px] h-8 text-xs">
              <SelectValue placeholder="Filter" />
            </SelectTrigger>
            <SelectContent>
              <SelectGroup>
                <SelectItem value="This Year">This Year</SelectItem>
                <SelectItem value="This Month">This Month</SelectItem>
                <SelectItem value="This Week">This Week</SelectItem>
              </SelectGroup>
            </SelectContent>
          </Select>
        )}
      </CardHeader>
      <CardContent className="flex-1">
        <ChartContainer config={barChartConfig}>
          <BarChart accessibilityLayer data={displayData} margin={{ top: 20, right: 10, left: 10, bottom: 0 }}>
            <CartesianGrid vertical={false} stroke="var(--border)" />
            <XAxis
              dataKey="month"
              tickLine={false}
              tickMargin={10}
              axisLine={false}
              tick={{ fill: 'var(--muted-foreground)', fontSize: 12 }}
            />
            <YAxis
              tickLine={false}
              axisLine={false}
              tickMargin={10}
              tick={{ fill: 'var(--muted-foreground)', fontSize: 12 }}
              tickFormatter={(val) => `£${val >= 1000 ? `${(val / 1000).toFixed(val % 1000 === 0 ? 0 : 1)}k` : val}`}
            />
            <ChartTooltip
              cursor={false}
              content={
                <ChartTooltipContent
                  formatter={(value) => (
                    <div className="flex items-center justify-between w-full min-w-[130px] gap-2">
                      <span className="text-muted-foreground">Sales Revenue</span>
                      <span className="  font-medium text-foreground tabular-nums">
                        £{Number(value || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                      </span>
                    </div>
                  )}
                />
              }
            />
            <Bar dataKey="revenue" fill="var(--color-revenue)" radius={[4, 4, 4, 4]} barSize={40} />
          </BarChart>
        </ChartContainer>
      </CardContent>
    </Card>
  )
}

const pieChartConfig = {
  value: { label: "Share" },
  customers: { label: "Clients", color: "var(--chart-1)" },
  companies: { label: "Companies", color: "var(--chart-2)" },
  orders: { label: "Orders", color: "var(--chart-3)" },
  tickets: { label: "Tickets", color: "var(--chart-4)" },
}

export function ChartPieSeparatorNone({ data = [], isLoading = false }) {
  if (isLoading) {
    return <Skeleton className="w-full h-[360px] rounded-xl" />
  }

  const pieData = data && data.length > 0 ? data : []
  const total = pieData.reduce((acc, curr) => acc + (curr.value || 0), 0)

  return (
    <Card className="flex flex-col h-full">
      <CardHeader className="flex flex-row items-center justify-between pb-2">
        <div className="space-y-1">
          <CardTitle>Portfolio Distribution</CardTitle>
        </div>
      </CardHeader>
      <div className="flex flex-col sm:flex-row items-center justify-center flex-1">
        <CardContent className="flex-[3] w-full">
          <ChartContainer
            config={pieChartConfig}
            className="mx-auto aspect-square max-h-[280px]"
          >
            <PieChart>
              <ChartTooltip
                cursor={false}
                content={<ChartTooltipContent hideLabel />}
              />
              <Pie
                data={pieData}
                dataKey="value"
                nameKey="category"
                stroke="0"
              />
            </PieChart>
          </ChartContainer>
        </CardContent>
        <div className="flex-[2] flex flex-col items-start gap-2.5 text-xs px-2 sm:px-0 mt-6 sm:mt-0">
          {pieData.map((item, index) => {
            const pct = item.pct ?? (total > 0 ? Math.round((item.value / total) * 100) : 0)
            return (
              <div key={index} className="flex items-center gap-2">
                <span className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: item.fill }}></span>
                <span className="text-foreground font-medium">{item.label} ({pct}%)</span>
              </div>
            )
          })}
        </div>
      </div>
    </Card>
  )
}

const areaChartConfig = {
  online: {
    label: "Online Activity",
    color: "var(--chart-1)",
  },
  offline: {
    label: "Direct Intakes",
    color: "var(--chart-2)",
  },
}

export function ChartAreaSalesTrend({ data = [], isLoading = false }) {
  if (isLoading) {
    return <Skeleton className="w-full h-[360px] rounded-xl" />
  }

  const displayData = data && data.length > 0 ? data : []

  return (
    <Card className="flex flex-col chart-revenue-privacy relative">
      <CardHeader>
        <div className="flex items-center justify-between">
          <CardTitle>Sales Trend</CardTitle>
          <div className="flex items-center gap-4 text-xs text-muted-foreground">
            <span className="flex items-center gap-1.5">
              <span className="w-2 h-2 rounded-full bg-primary"></span> Online Activity
            </span>
            <span className="flex items-center gap-1.5">
              <span className="w-2 h-2 rounded-full bg-muted-foreground/30"></span> Direct Intake
            </span>
          </div>
        </div>
      </CardHeader>
      <CardContent className="flex-1 pt-6 px-2 sm:px-6">
        <ChartContainer config={areaChartConfig} className="w-full h-full min-h-[250px]">
          <AreaChart
            accessibilityLayer
            data={displayData}
            margin={{
              left: -20,
              right: 12,
              top: 10,
              bottom: 0
            }}
          >
            <CartesianGrid vertical={false} stroke="var(--border)" />
            <XAxis
              dataKey="week"
              tickLine={false}
              axisLine={false}
              tickMargin={8}
              tick={{ fill: 'var(--muted-foreground)', fontSize: 12 }}
            />
            <YAxis
              tickLine={false}
              axisLine={false}
              tickMargin={8}
              tick={{ fill: 'var(--muted-foreground)', fontSize: 12 }}
            />
            <ChartTooltip cursor={false} content={<ChartTooltipContent />} />
            <Area
              dataKey="online"
              type="natural"
              fill="var(--color-online)"
              fillOpacity={0.2}
              stroke="var(--color-online)"
              strokeWidth={2}
              dot={false}
              activeDot={false}
            />
            <Area
              dataKey="offline"
              type="natural"
              fill="var(--color-offline)"
              fillOpacity={0.4}
              stroke="var(--color-offline)"
              strokeWidth={2}
              dot={false}
              activeDot={false}
            />
          </AreaChart>
        </ChartContainer>
      </CardContent>
    </Card>
  )
}

const topPerformerConfig = {
  score: {
    label: "Score",
    color: "var(--chart-3)",
  },
}

export function ChartTopPerformer({ data = [], isLoading = false }) {
  if (isLoading) {
    return <Skeleton className="w-full h-[360px] rounded-xl" />
  }

  const displayData = data && data.length > 0 ? data : []

  return (
    <Card className="flex flex-col">
      <CardHeader>
        <CardTitle>Completion & Operations</CardTitle>
      </CardHeader>
      <CardContent className="flex-1 min-h-[250px] pt-4 px-2 sm:px-6">
        <ChartContainer config={topPerformerConfig} className="w-full h-full min-h-[250px]">
          <BarChart
            accessibilityLayer
            data={displayData}
            layout="vertical"
            margin={{
              left: 0,
              right: 32,
            }}
          >
            <CartesianGrid horizontal={false} vertical={true} stroke="var(--border)" />
            <YAxis
              dataKey="team"
              type="category"
              tickLine={false}
              axisLine={false}
              hide={true}
            />
            <XAxis type="number" hide={true} />
            <ChartTooltip cursor={false} content={<ChartTooltipContent />} />
            <Bar dataKey="score" fill="var(--color-score)" radius={6} barSize={28}>
              <LabelList dataKey="team" position="insideLeft" fill="var(--background)" offset={12} fontSize={14} />
              <LabelList dataKey="score" position="right" fill="var(--foreground)" offset={12} fontSize={14} />
            </Bar>
          </BarChart>
        </ChartContainer>
      </CardContent>
    </Card>
  )
}

import * as React from "react"
import { useTable } from "@tanstack/react-table"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Skeleton } from "@/components/ui/skeleton"
import { IconAdjustmentsHorizontal, IconSearch, IconX, IconMoodEmpty, IconTrash } from "@tabler/icons-react"
import { features } from "./data-table-features"

import { cn } from "cn"

export const DataTable = ({
  columns,
  data,
  filterConfig,
  onDeleteSelected,
  isLoading = false,
  searchValue,
  onSearchChange,
  searchPlaceholder = "Search data...",
  onClearFilters,
  hideSearch = false,
}) => {
  const isSearchControlled = typeof onSearchChange === "function"
  const [sorting, setSorting] = React.useState([])
  const [columnFilters, setColumnFilters] = React.useState([])
  const [globalFilter, setGlobalFilter] = React.useState("")
  const [columnVisibility, setColumnVisibility] = React.useState({})
  const [rowSelection, setRowSelection] = React.useState({})
  const [pagination, setPagination] = React.useState({ pageIndex: 0, pageSize: data?.length || 9999 })

  // Always show all rows on one page
  React.useEffect(() => {
    if (data?.length) {
      setPagination(prev => ({ ...prev, pageSize: data.length }))
    }
  }, [data?.length])

  const table = useTable({
    features,
    data: data || [],
    columns,
    onSortingChange: setSorting,
    onColumnFiltersChange: setColumnFilters,
    onGlobalFilterChange: setGlobalFilter,
    onColumnVisibilityChange: setColumnVisibility,
    onRowSelectionChange: setRowSelection,
    onPaginationChange: setPagination,
    globalFilterFn: "includesString",
    state: {
      sorting,
      columnFilters,
      globalFilter: isSearchControlled ? "" : globalFilter,
      columnVisibility,
      rowSelection,
      pagination,
    },
  })

  const [filterResetKey, setFilterResetKey] = React.useState(0)

  const hasControlledFilterActive = (filterConfig || []).some((config) => {
    if (config.value === undefined) return false
    const v = config.value
    return v != null && v !== "" && v !== "all"
  })

  const searchDisplay = isSearchControlled ? (searchValue ?? "") : (globalFilter ?? "")
  const hasLocalFilters = !isSearchControlled && (!!globalFilter || columnFilters.length > 0)
  const showClear = hasControlledFilterActive || hasLocalFilters || (isSearchControlled && !!String(searchValue || "").trim())

  const handleClearFilters = () => {
    if (typeof onClearFilters === "function") {
      onClearFilters()
    }
    if (!isSearchControlled) {
      setGlobalFilter("")
    }
    table.resetColumnFilters()
    setColumnFilters([])
    setFilterResetKey((prev) => prev + 1)
  }

  return (
    <div>
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between py-4 gap-4">
        <div className="flex items-center gap-2 flex-wrap flex-1">
          {!hideSearch && (
            <div className="relative">
              <IconSearch className="absolute left-2.5 top-1.5 h-3.5 w-3.5 text-muted-foreground" />
              <Input
                placeholder={searchPlaceholder}
                value={searchDisplay}
                className="max-w-xs pl-8 text-xs"
                onChange={(event) => {
                  if (isSearchControlled) onSearchChange(event.target.value)
                  else setGlobalFilter(event.target.value)
                }}
                disabled={isLoading}
              />
            </div>
          )}
          {filterConfig && filterConfig.map((config) => {
            const isControlled = config.value !== undefined && typeof config.onValueChange === "function"
            const column = !isControlled && config.columnKey ? table.getColumn(config.columnKey) : null
            const currentValue = isControlled
              ? (config.value === "all" || config.value == null || config.value === "" ? null : config.value)
              : column?.getFilterValue()

            return (
              <Select
                key={`${config.key || config.columnKey}-${filterResetKey}-${currentValue ?? "none"}`}
                value={currentValue ?? null}
                onValueChange={(val) => {
                  if (isControlled) config.onValueChange(val === "all" ? "all" : val)
                  else column?.setFilterValue(val === "all" ? undefined : val)
                }}
                disabled={isLoading}
              >
                <SelectTrigger className={cn("h-8 text-xs", config.triggerClassName || "w-35")}>
                  <SelectValue placeholder={config.placeholder} />
                </SelectTrigger>
                <SelectContent className={cn("min-w-[var(--radix-select-trigger-width)]", config.contentClassName)}>
                  <SelectGroup>
                    <SelectItem value="all">{config.allLabel || "All"}</SelectItem>
                    {config.options.map((opt) => (
                      <SelectItem key={opt.value} value={opt.value} className="text-xs">
                        {opt.label}
                      </SelectItem>
                    ))}
                  </SelectGroup>
                </SelectContent>
              </Select>
            )
          })}

          {showClear && (
            <Button
              variant="destructive"
              size="sm"
              onClick={handleClearFilters}
              className="h-7"
            >
              Clear
              <IconX className="ml-1 h-4 w-4" />
            </Button>
          )}
        </div>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="outline" size="sm" className="ml-auto h-7" disabled={isLoading}>
              <IconAdjustmentsHorizontal className="mr-2 h-4 w-4" />
              Columns
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            {table
              .getAllColumns()
              .filter((column) => column.getCanHide())
              .map((column) => {
                return (
                  <DropdownMenuCheckboxItem
                    key={column.id}
                    className="capitalize"
                    checked={column.getIsVisible()}
                    onCheckedChange={(value) =>
                      column.toggleVisibility(!!value)
                    }
                  >
                    {column.id}
                  </DropdownMenuCheckboxItem>
                )
              })}
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
      <div className="overflow-x-auto rounded-md border bg-card">
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id} className="relative">
                {headerGroup.headers.map((header) => {
                  const isSelect = header.id === "select";
                  const hasSelection = table.getFilteredSelectedRowModel().rows.length > 0;

                  return (
                    <TableHead key={header.id}>
                      {header.isPlaceholder ? null : (
                        <div 
                          className={cn(
                            "transition-all duration-300 ease-in-out",
                            hasSelection && !isSelect ? "opacity-0 translate-y-2 pointer-events-none" : "opacity-100 translate-y-0"
                          )}
                        >
                          <table.FlexRender header={header} />
                        </div>
                      )}
                    </TableHead>
                  )
                })}

                {/* Selected Count Overlay */}
                {table.getFilteredSelectedRowModel().rows.length > 0 && (
                  <div className="absolute inset-y-0 left-10 flex items-center z-10 animate-in fade-in slide-in-from-left-8 duration-400">
                    <span className="text-sm font-medium text-muted-foreground">
                      {table.getFilteredSelectedRowModel().rows.length} {table.getFilteredSelectedRowModel().rows.length === 1 ? 'Row' : 'Rows'} Selected
                    </span>
                  </div>
                )}

                {/* Delete Button Overlay */}
                {table.getFilteredSelectedRowModel().rows.length > 0 && (
                  <div className="absolute inset-y-0 right-4 flex items-center justify-end z-10 animate-in fade-in slide-in-from-right-4 duration-400">
                    <Button 
                      variant="destructive" 
                      size="sm" 
                      onClick={() => onDeleteSelected?.(table.getFilteredSelectedRowModel().rows)}
                    >
                      <IconTrash className="mr-1 h-4.5 w-4.5" />
                      Delete ({table.getFilteredSelectedRowModel().rows.length})
                    </Button>
                  </div>
                )}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {isLoading ? (
              Array.from({ length: 8 }).map((_, rIdx) => (
                <TableRow key={rIdx} className="hover:bg-transparent h-[52px]">
                  {columns.map((col, cIdx) => (
                    <TableCell key={cIdx}>
                      <Skeleton 
                        className={cn(
                          "h-4",
                          cIdx === 0 ? "size-4 rounded-sm" :
                          cIdx === 1 ? "w-16 h-5 rounded-full" :
                          cIdx === 2 ? "w-12 h-4" :
                          cIdx === 3 ? "w-32 h-4" :
                          cIdx === 4 ? "w-24 h-4" :
                          cIdx === columns.length - 1 ? "size-7 rounded-md" :
                          "w-20 h-4"
                        )} 
                      />
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : table.getRowModel().rows?.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() && "selected"}
                  className="min-h-[52px] h-auto"
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id}>
                      <table.FlexRender cell={cell} />
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell colSpan={columns.length} className="h-32 text-center text-muted-foreground">
                  <IconMoodEmpty className="mx-auto mb-3 size-10"/>
                  No records found! Clear all filters and try again.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
      <div className={cn("flex items-center justify-between py-3 px-1 text-xs text-muted-foreground", isLoading && "invisible")}>
        <span>
          {table.getFilteredSelectedRowModel().rows.length > 0
            ? `${table.getFilteredSelectedRowModel().rows.length} of ${table.getFilteredRowModel().rows.length} row(s) selected`
            : `${table.getFilteredRowModel().rows.length} row(s) total`
          }
        </span>
      </div>
    </div>
  )
}
export default DataTable;

"use client"
import React from "react"
import { Badge } from "@/components/ui/badge"
import {
  Card,
  CardAction,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { IconTrendingUp, IconTrendingDown } from "@tabler/icons-react"
import { cn } from "cn"

/* Inline shimmer bar — replaces Skeleton without changing card dimensions */
function Shimmer({ className }) {
  return (
    <span
      className={cn(
        "inline-block rounded-md bg-muted animate-pulse",
        className
      )}
    />
  )
}

export function StatCard({
  title,
  value,
  trendValue,
  trendDirection = "up",
  footerText,
  footerSubText,
  isLoading = false,
  compact = false,
  onClick,
  active = false,
}) {
  const isDown = trendDirection === "down"
  const TrendIcon = isDown ? IconTrendingDown : IconTrendingUp
  const interactive = typeof onClick === "function"

  return (
    <Card
      size={compact ? "sm" : "default"}
      className={cn(
        "@container/card",
        interactive && "cursor-pointer transition-colors hover:bg-muted/30",
        active && "ring-1 ring-primary/40 border-primary/30"
      )}
      onClick={interactive ? onClick : undefined}
      role={interactive ? "button" : undefined}
      tabIndex={interactive ? 0 : undefined}
      onKeyDown={
        interactive
          ? (e) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault()
                onClick()
              }
            }
          : undefined
      }
    >
      <CardHeader className={compact ? "gap-0.5" : undefined}>
        <CardDescription className={compact ? "text-[11px]" : undefined}>
          {isLoading ? <Shimmer className="h-3 w-20" /> : title}
        </CardDescription>
        <CardTitle
          className={cn(
            "font-semibold tabular-nums",
            typeof value === "string" && /[£$€]/.test(value) && "privacy-currency-mask",
            compact
              ? "text-xl @[250px]/card:text-2xl"
              : "text-2xl @[250px]/card:text-3xl"
          )}
        >
          {isLoading ? <Shimmer className={compact ? "h-6 w-16 mt-0.5" : "h-8 w-20 mt-1"} /> : value}
        </CardTitle>
        {(trendValue || isLoading) && (
          <CardAction>
            {isLoading ? (
              <Shimmer className="h-5 w-12 rounded-full" />
            ) : (
              <Badge
                variant="outline"
                className={cn(
                  "gap-1 font-medium",
                  compact && "px-1.5 py-0 text-[10px]",
                  isDown
                    ? "text-rose-600 border-rose-200 dark:border-rose-900/50 bg-rose-50/50 dark:bg-rose-950/20"
                    : "text-emerald-600 dark:text-emerald-400 border-emerald-200 dark:border-emerald-900/50 bg-emerald-50/50 dark:bg-emerald-950/20"
                )}
              >
                <TrendIcon className={compact ? "size-3" : "size-3.5"} />
                {trendValue}
              </Badge>
            )}
          </CardAction>
        )}
      </CardHeader>
      {(footerText || footerSubText || isLoading) && (
        <CardFooter
          className={cn(
            "flex-col items-start",
            compact ? "gap-0.5 pt-0 text-[11px]" : "gap-1.5 text-sm"
          )}
        >
          {isLoading ? (
            <Shimmer className="h-3 w-28" />
          ) : (
            <>
              {footerText && (
                <div className="line-clamp-1 flex gap-1.5 font-medium">
                  {footerText} {!compact && <TrendIcon className="size-4" />}
                </div>
              )}
              {footerSubText && (
                <div className="text-muted-foreground line-clamp-1">{footerSubText}</div>
              )}
            </>
          )}
        </CardFooter>
      )}
    </Card>
  )
}

export function SectionCards({ stats = [], isLoading = false, compact = false }) {
  /* Use stats.length when loaded, fall back to 4 placeholders while loading */
  const items = isLoading
    ? Array.from({ length: stats.length || 4 }).map(() => ({}))
    : stats

  const count = items.length
  const gridCols =
    count >= 6
      ? "grid-cols-2 sm:grid-cols-3 lg:grid-cols-6"
      : count === 5
        ? "grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5"
        : "grid-cols-1 sm:grid-cols-2 lg:grid-cols-4"

  return (
    <div
      className={cn(
        "grid gap-3 *:data-[slot=card]:bg-linear-to-t *:data-[slot=card]:from-primary/5 *:data-[slot=card]:to-card *:data-[slot=card]:shadow-xs dark:*:data-[slot=card]:bg-card",
        gridCols
      )}
    >
      {items.map((stat, index) => (
        <StatCard key={stat.title || index} {...stat} compact={compact} isLoading={isLoading} />
      ))}
    </div>
  )
}

