import React, { useState, useEffect, useRef } from 'react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group'
import { Select, SelectContent, SelectGroup, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { ScrollArea } from '@/components/ui/scroll-area'
import { IconBuildingPlus, IconAlertCircle, IconLoader2, IconSearch, IconCheck, IconBuilding } from '@tabler/icons-react'
import { toast } from 'sonner'
import { toastProcessing, toastDone, toastFail } from '@/lib/toastActions'
import ToastSave from '@/components/ToastSave'

const AddCompany = ({ isOpen, onClose }) => {
  // Search state
  const [searchQuery, setSearchQuery] = useState('')
  const [searchResults, setSearchResults] = useState([])
  const [isSearching, setIsSearching] = useState(false)
  const [showDropdown, setShowDropdown] = useState(false)
  const [isAutoFilling, setIsAutoFilling] = useState(false)
  const [isAutoFilled, setIsAutoFilled] = useState(false)
  const [showUnsavedToast, setShowUnsavedToast] = useState(false)
  const [toastSaveState, setToastSaveState] = useState('initial')
  const searchTimeoutRef = useRef(null)
  const dropdownRef = useRef(null)

  // Form fields
  const [companyName, setCompanyName] = useState('')
  const [companyNumber, setCompanyNumber] = useState('')
  const [incorporationDate, setIncorporationDate] = useState('')
  const [director, setDirector] = useState('')
  const [status, setStatus] = useState('Active')
  const [regOffice, setRegOffice] = useState('71-75 Shelton Street, Covent Garden, London, WC2H 9JQ')

  // Client Assignment
  const [clientType, setClientType] = useState('existing')
  const [selectedClientId, setSelectedClientId] = useState('')
  const [newClientName, setNewClientName] = useState('')
  const [newClientEmail, setNewClientEmail] = useState('')

  const [clients, setClients] = useState([])
  const [isLoadingClients, setIsLoadingClients] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [errorMsg, setErrorMsg] = useState('')

  // Load clients on modal open
  useEffect(() => {
    if (isOpen) {
      handleReset()
      loadClients()
    }
  }, [isOpen])

  // Click outside to close search dropdown
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target)) {
        setShowDropdown(false)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  const loadClients = async () => {
    setIsLoadingClients(true)
    try {
      const apiUrl = import.meta.env.VITE_API_URL || '/api'
      const token = localStorage.getItem('token')
      const res = await fetch(`${apiUrl}/admin/customers`, {
        credentials: 'include',
        headers: {
          'Content-Type': 'application/json',
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
        },
      })
      if (res.ok) {
        const data = await res.json()
        const raw = data.customers || data.data?.customers || (Array.isArray(data.data) ? data.data : [])
        setClients(Array.isArray(raw) ? raw : [])
        if (Array.isArray(raw) && raw.length > 0 && !selectedClientId) {
          setSelectedClientId(String(raw[0].id))
        }
      }
    } catch (err) {
      console.error('Failed to load customers in AddCompany:', err)
    } finally {
      setIsLoadingClients(false)
    }
  }

  // Companies House Live Search
  const handleSearchChange = (val) => {
    setSearchQuery(val)
    if (searchTimeoutRef.current) clearTimeout(searchTimeoutRef.current)

    const trimmed = val.trim()
    if (!trimmed || trimmed.length < 2) {
      setSearchResults([])
      setShowDropdown(false)
      return
    }

    searchTimeoutRef.current = setTimeout(async () => {
      setIsSearching(true)
      try {
        const apiUrl = import.meta.env.VITE_API_URL || '/api'
        const token = localStorage.getItem('token')
        const res = await fetch(`${apiUrl}/admin/companies/lookup-ch?query=${encodeURIComponent(trimmed)}`, {
          credentials: 'include',
          headers: {
            'Content-Type': 'application/json',
            ...(token ? { Authorization: `Bearer ${token}` } : {}),
          },
        })
        if (res.ok) {
          const data = await res.json()
          const items = data.data?.results || []
          setSearchResults(items)
          setShowDropdown(items.length > 0)
        }
      } catch (err) {
        console.error('Live search error:', err)
      } finally {
        setIsSearching(false)
      }
    }, 350)
  }

  // Auto-fill company details from selected Companies House result
  const handleSelectCompany = async (comp) => {
    setShowDropdown(false)
    setIsAutoFilling(true)
    setErrorMsg('')
    const toastId = toastProcessing('Loading company details…')
    try {
      const apiUrl = import.meta.env.VITE_API_URL || '/api'
      const token = localStorage.getItem('token')
      const res = await fetch(`${apiUrl}/admin/companies/lookup-ch?number=${encodeURIComponent(comp.company_number)}`, {
        credentials: 'include',
        headers: {
          'Content-Type': 'application/json',
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
        },
      })
      if (res.ok) {
        const data = await res.json()
        const d = data.data || {}
        setCompanyName(d.company_name || comp.company_name || '')
        setCompanyNumber(d.company_number || comp.company_number || '')
        setIncorporationDate(d.incorporation_date || '')
        if (d.director) setDirector(d.director)
        if (d.reg_office) setRegOffice(d.reg_office)
        if (d.status) setStatus(d.status)
        setIsAutoFilled(true)
        setSearchQuery(`${d.company_name || comp.company_name} (${d.company_number || comp.company_number})`)
        toastDone(toastId, `Loaded official details for ${d.company_name || 'company'}!`)
      } else {
        // Fallback to basic search result
        setCompanyName(comp.company_name || '')
        setCompanyNumber(comp.company_number || '')
        if (comp.incorporation_date) setIncorporationDate(comp.incorporation_date)
        if (comp.status) setStatus(comp.status)
        setIsAutoFilled(true)
        toastDone(toastId, `Loaded details for ${comp.company_name}`)
      }
    } catch (err) {
      toastFail(toastId, 'Failed to fetch full company details: ' + err.message)
    } finally {
      setIsAutoFilling(false)
    }
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    setErrorMsg('')

    if (!companyName.trim()) {
      setErrorMsg('Company name is required')
      return
    }

    if (clientType === 'new' && (!newClientName.trim() || !newClientEmail.trim())) {
      setErrorMsg('Please enter the new client name and email')
      return
    }

    setIsSubmitting(true)
    const toastId = toastProcessing('Creating company…')
    try {
      const apiUrl = import.meta.env.VITE_API_URL || '/api'
      const token = localStorage.getItem('token')
      const payload = {
        company_name: companyName.trim(),
        company_number: companyNumber.trim(),
        incorporation_date: incorporationDate,
        director: director.trim(),
        status,
        reg_office: regOffice.trim(),
        client_mode: clientType,
        client_id: clientType === 'existing' ? selectedClientId : undefined,
        new_client_full_name: clientType === 'new' ? newClientName.trim() : undefined,
        new_client_email: clientType === 'new' ? newClientEmail.trim() : undefined,
      }

      const res = await fetch(`${apiUrl}/admin/companies`, {
        method: 'POST',
        credentials: 'include',
        headers: {
          'Content-Type': 'application/json',
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
        },
        body: JSON.stringify(payload),
      })

      const data = await res.json().catch(() => ({}))

      if (!res.ok || data.success === false) {
        throw new Error(data.message || 'Failed to create company')
      }

      toastDone(toastId, data.message || 'Company created successfully!')
      handleReset()
      onClose()
    } catch (err) {
      const msg = err.message || 'An error occurred while creating company'
      setErrorMsg(msg)
      toastFail(toastId, msg)
    } finally {
      setIsSubmitting(false)
    }
  }

  const isDirty = Boolean(
    companyName.trim() ||
    companyNumber.trim() ||
    director.trim() ||
    newClientName.trim() ||
    newClientEmail.trim() ||
    isAutoFilled
  )

  const handleAttemptClose = () => {
    if (isSubmitting) return
    if (isDirty) {
      setShowUnsavedToast(true)
    } else {
      onClose()
    }
  }

  const handleReset = () => {
    setSearchQuery('')
    setSearchResults([])
    setShowDropdown(false)
    setCompanyName('')
    setCompanyNumber('')
    setIncorporationDate('')
    setDirector('')
    setStatus('Active')
    setRegOffice('71-75 Shelton Street, Covent Garden, London, WC2H 9JQ')
    setNewClientName('')
    setNewClientEmail('')
    setIsAutoFilled(false)
    setErrorMsg('')
    setShowUnsavedToast(false)
  }

  return (
    <>
      <Dialog open={isOpen} onOpenChange={(open) => { if (!open) handleAttemptClose() }}>
        <DialogContent className="sm:max-w-140 p-0 overflow-hidden">
          <DialogHeader className="p-6 pb-2">
            <DialogTitle className="text-xl">Add Company</DialogTitle>
            <DialogDescription className="text-xs text-muted-foreground mt-0.5">
              Search UK Companies House to auto-fill official records or enter details manually.
            </DialogDescription>
          </DialogHeader>

        <ScrollArea className="max-h-[75vh]">
          <form onSubmit={handleSubmit} className="p-6 pt-2 space-y-4">
            {errorMsg && (
              <div className="p-3 rounded-lg bg-destructive/10 border border-destructive/20 text-destructive text-xs flex items-center gap-2">
                <IconAlertCircle className="h-4 w-4 shrink-0" />
                <span>{errorMsg}</span>
              </div>
            )}

            {/* Step 1: Companies House Live Search & Auto-Fill */}
            <div className="space-y-1.5 relative" ref={dropdownRef}>
              <div className="flex items-center justify-between">
                <Label htmlFor="ch-search" className="text-sm font-semibold">
                  Search Companies House
                </Label>
                <span className="text-[10px] text-muted-foreground">Type name or 8-digit number to auto-fill</span>
              </div>
              <div className="relative">
                <IconSearch className="absolute left-2.5 top-1.5 h-4 w-4 text-muted-foreground" />
                <Input
                  id="ch-search"
                  placeholder="Number or Name"
                  className="pl-8"
                  value={searchQuery}
                  onChange={(e) => handleSearchChange(e.target.value)}
                  onFocus={() => searchResults.length > 0 && setShowDropdown(true)}
                  disabled={isSubmitting || isAutoFilling}
                />
                {(isSearching || isAutoFilling) && (
                  <IconLoader2 className="absolute right-2.5 top-1.5 h-4 w-4 text-primary animate-spin" />
                )}
              </div>

              {/* Suggestions dropdown */}
              {showDropdown && searchResults.length > 0 && (
                <div className="absolute top-full left-0 right-0 mt-1 bg-popover border rounded-lg shadow-xl z-50 overflow-hidden">
                  <ScrollArea className="max-h-56 w-full">
                    <div className="divide-y divide-border/40 p-1">
                      {searchResults.map((item, idx) => (
                        <div
                          key={idx}
                          onClick={() => handleSelectCompany(item)}
                          className="p-2.5 rounded-md hover:bg-accent cursor-pointer flex items-center justify-between gap-2 text-xs transition-colors"
                        >
                          <div className="overflow-hidden">
                            <p className="font-semibold truncate text-foreground flex items-center gap-1.5">
                              <IconBuilding className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
                              <span className="truncate">{item.company_name}</span>
                            </p>
                            <p className="text-[11px] text-muted-foreground mt-0.5 truncate">
                              {item.company_number} • {item.address_snippet || 'UK'}
                            </p>
                          </div>
                          <Badge className={item.status === 'Active' ? 'badge-green shrink-0 text-[10px]' : 'badge-amber shrink-0 text-[10px]'}>
                            {item.status}
                          </Badge>
                        </div>
                      ))}
                    </div>
                  </ScrollArea>
                </div>
              )}
            </div>

            {/* Step 2: Client Assignment Mode */}
            <div className="space-y-2 pt-1">
              <Label className="text-sm font-semibold">
                Client Account <span className="text-destructive">*</span>
              </Label>

              <div className="flex items-center gap-4 flex-wrap">
                <RadioGroup
                  value={clientType}
                  onValueChange={setClientType}
                  className="flex items-center gap-4 w-auto shrink-0"
                  disabled={isSubmitting}
                >
                  <Label
                    htmlFor="add-comp-client-existing"
                    className="flex items-center gap-1.5 cursor-pointer text-xs font-medium"
                  >
                    <RadioGroupItem value="existing" id="add-comp-client-existing" />
                    <span>Existing Client</span>
                  </Label>

                  <Label
                    htmlFor="add-comp-client-new"
                    className="flex items-center gap-1.5 cursor-pointer text-xs font-medium"
                  >
                    <RadioGroupItem value="new" id="add-comp-client-new" />
                    <span>New Client</span>
                  </Label>
                </RadioGroup>

                {clientType === 'existing' && (
                  <div className="w-64 sm:w-72">
                    {(() => {
                      const selectedClient = clients.find((c) => String(c.id) === String(selectedClientId))
                      return (
                        <Select
                          value={selectedClientId}
                          onValueChange={setSelectedClientId}
                          disabled={isSubmitting || isLoadingClients}
                        >
                          <SelectTrigger className="w-full h-8 text-xs">
                            <SelectValue placeholder={isLoadingClients ? 'Loading clients...' : 'Select client...'}>
                              {selectedClient ? (selectedClient.name || selectedClient.full_name || 'Customer') : undefined}
                            </SelectValue>
                          </SelectTrigger>
                          <SelectContent className="max-h-68 w-(--anchor-width) overflow-hidden p-0">
                            <ScrollArea className="h-68 w-full p-1">
                              <SelectGroup>
                                {clients.map((c) => (
                                  <SelectItem key={c.id} value={String(c.id)} className="text-xs py-1.5 cursor-pointer">
                                    {c.name || c.full_name || 'Customer'}
                                  </SelectItem>
                                ))}
                              </SelectGroup>
                            </ScrollArea>
                          </SelectContent>
                        </Select>
                      )
                    })()}
                  </div>
                )}
              </div>

              {clientType === 'new' && (
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-1">
                  <div className="space-y-1">
                    <Label htmlFor="add-new-client-name" className="text-xs font-normal">Full Name</Label>
                    <Input
                      id="add-new-client-name"
                      placeholder="e.g. John Doe"
                      className="text-xs"
                      value={newClientName}
                      onChange={(e) => setNewClientName(e.target.value)}
                      disabled={isSubmitting}
                    />
                  </div>
                  <div className="space-y-1">
                    <Label htmlFor="add-new-client-email" className="text-xs font-normal">Email Address</Label>
                    <Input
                      id="add-new-client-email"
                      type="email"
                      placeholder="e.g. john@example.com"
                      className="text-xs"
                      value={newClientEmail}
                      onChange={(e) => setNewClientEmail(e.target.value)}
                      disabled={isSubmitting}
                    />
                  </div>
                </div>
              )}
            </div>

            {/* Step 3: Company Details (Auto-filled / Editable) */}
            <div className="space-y-3 pt-1">
              <div className="flex items-center justify-between">
                <Label className="text-sm font-semibold">Company Details</Label>
                {isAutoFilled && (
                  <span className="text-[11px] text-emerald-600 dark:text-emerald-400 font-medium flex items-center gap-1">
                    <IconCheck className="h-3.5 w-3.5" /> Details populated
                  </span>
                )}
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div className="space-y-1 sm:col-span-2">
                  <Label htmlFor="add-comp-name" className="text-xs font-normal">
                    Company Name <span className="text-destructive">*</span>
                  </Label>
                  <Input
                    id="add-comp-name"
                    placeholder="e.g. Acme Innovations Ltd"
                    className="text-xs"
                    value={companyName}
                    onChange={(e) => setCompanyName(e.target.value)}
                    disabled={isSubmitting}
                  />
                </div>

                <div className="space-y-1">
                  <Label htmlFor="add-comp-num" className="text-xs font-normal">
                    Company Number <span className="text-muted-foreground text-[10px]">(Optional)</span>
                  </Label>
                  <Input
                    id="add-comp-num"
                    placeholder="e.g. 12345678"
                    className="text-xs"
                    value={companyNumber}
                    onChange={(e) => setCompanyNumber(e.target.value)}
                    disabled={isSubmitting}
                  />
                </div>

                <div className="space-y-1">
                  <Label htmlFor="add-comp-date" className="text-xs font-normal">
                    Incorporation Date
                  </Label>
                  <Input
                    id="add-comp-date"
                    type="date"
                    className="text-xs"
                    value={incorporationDate}
                    onChange={(e) => setIncorporationDate(e.target.value)}
                    disabled={isSubmitting}
                  />
                </div>

                <div className="space-y-1">
                  <Label htmlFor="add-comp-director" className="text-xs font-normal">
                    Director Name
                  </Label>
                  <Input
                    id="add-comp-director"
                    placeholder="e.g. John Smith"
                    className="text-xs"
                    value={director}
                    onChange={(e) => setDirector(e.target.value)}
                    disabled={isSubmitting}
                  />
                </div>

                <div className="space-y-1">
                  <Label className="text-xs font-normal">Status</Label>
                  <Select value={status} onValueChange={setStatus} disabled={isSubmitting}>
                    <SelectTrigger className="w-full h-8 text-xs">
                      <SelectValue placeholder="Status" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectGroup>
                        <SelectItem value="Active" className="text-xs">Active</SelectItem>
                        <SelectItem value="Inactive" className="text-xs">Inactive</SelectItem>
                        <SelectItem value="Dissolved" className="text-xs">Dissolved</SelectItem>
                      </SelectGroup>
                    </SelectContent>
                  </Select>
                </div>

                <div className="space-y-1 sm:col-span-2">
                  <Label htmlFor="add-comp-office" className="text-xs font-normal">
                    Registered Office Address
                  </Label>
                  <Input
                    id="add-comp-office"
                    placeholder="Registered address"
                    className="text-xs"
                    value={regOffice}
                    onChange={(e) => setRegOffice(e.target.value)}
                    disabled={isSubmitting}
                  />
                </div>
              </div>
            </div>

            {/* Footer */}
            <DialogFooter className="pt-3 gap-2">
              <Button type="button" variant="ghost" size="sm" onClick={handleAttemptClose} disabled={isSubmitting}>
                Cancel
              </Button>
              <Button type="submit" size="sm" disabled={isSubmitting}>
                {isSubmitting ? (
                  <>
                    <IconLoader2 className="mr-2 h-4 w-4 animate-spin" />
                    Creating...
                  </>
                ) : (
                  <>
                    <IconBuildingPlus className="mr-2 h-4 w-4" />
                    Add Company
                  </>
                )}
              </Button>
            </DialogFooter>
          </form>
        </ScrollArea>
      </DialogContent>
    </Dialog>

    <ToastSave
      open={isOpen && showUnsavedToast}
      state={toastSaveState}
      initialText="You have unsaved company details. Discard and close?"
      discardText="Discard & Close"
      saveText="Add Company"
      cancelText="Keep Editing"
      onCancel={() => setShowUnsavedToast(false)}
      onDiscard={() => {
        handleReset()
        onClose()
      }}
      onSave={async (e) => {
        setToastSaveState('loading')
        try {
          await handleSubmit(e || { preventDefault: () => {} })
          setToastSaveState('success')
          setTimeout(() => {
            setShowUnsavedToast(false)
            setToastSaveState('initial')
          }, 700)
        } catch (err) {
          setToastSaveState('initial')
        }
      }}
    />
  </>
  )
}

export default AddCompany

import React, { useState, useEffect } from 'react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Checkbox } from '@/components/ui/checkbox'
import { Skeleton } from '@/components/ui/skeleton'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog'
import {
  IconUpload,
  IconBuildingPlus,
  IconSearch,
  IconRefresh,
  IconTrash,
  IconAlertTriangle,
  IconLoader2,
  IconCheck,
} from '@tabler/icons-react'
import CompanyCard from './CompanyCard'
import AddCompany from './AddCompany'
import ImportWebfilingModal from './ImportWebfilingModal'
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { toast } from 'sonner'
import { toastUndoableDelete } from '@/lib/toastActions'
import { Card, CardContent } from '@/components/ui/card'
import DeleteConfirmation from '@/components/DeleteConfirmation'
import { apiRequest, getApiBase, toastApiEmpty } from '@/lib/api'

const Companies = () => {
  const [isAddModalOpen, setIsAddModalOpen] = useState(false)
  const [isWebfilingModalOpen, setIsWebfilingModalOpen] = useState(false)
  const [searchTerm, setSearchTerm] = useState('')
  const [companies, setCompanies] = useState([])
  const [isLoading, setIsLoading] = useState(true)
  const [loadError, setLoadError] = useState(null)
  const [activeTab, setActiveTab] = useState('all')

  // Selection & Bulk delete state
  const [selectedIds, setSelectedIds] = useState([])
  const [isDeleting, setIsDeleting] = useState(false)
  const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false)
  const [singleDeleteId, setSingleDeleteId] = useState(null)

  const fetchCompanies = async () => {
    setIsLoading(true)
    setLoadError(null)
    try {
      const res = await apiRequest('/admin/companies?limit=500', { label: 'Companies' })
      if (!res.ok) {
        setCompanies([])
        setLoadError(res.reason)
        return
      }
      const data = res.data || {}
      const rawList =
        data.companies ||
        data.data?.companies ||
        (Array.isArray(data.data) ? data.data : null) ||
        (Array.isArray(data) ? data : [])
      if (Array.isArray(rawList)) {
        setCompanies(
          rawList.map((c) => ({
            id: c.id,
            name: c.company_name || c.name || 'Unnamed Company',
            number: c.company_number || c.number || '#00000000',
            director: c.director_name || c.director || 'Director',
            address: c.registered_office_address || c.reg_office || c.address || 'United Kingdom',
            status: c.status || 'Active',
            incDate: c.incorporation_date || c.inc_date || null,
            countryFlag: '🇬🇧',
            countryName: 'UK',
            deadlineText: c.accounts_next_due ? `Accounts due: ${c.accounts_next_due}` : 'No upcoming deadlines',
            raw: c,
          }))
        )
        if (rawList.length === 0) toastApiEmpty('Companies', getApiBase())
        return
      }
      setCompanies([])
      setLoadError('API returned an unexpected response shape (no companies list).')
      toast.error('Companies failed to load', {
        description: 'API returned an unexpected response shape (no companies list).',
        duration: 8000,
      })
    } catch (err) {
      console.error('Failed to load companies:', err)
      setCompanies([])
      setLoadError(err?.message || 'Unexpected error')
      toast.error('Companies failed to load', {
        description: err?.message || 'Unexpected error',
        duration: 8000,
      })
    } finally {
      setIsLoading(false)
    }
  }

  useEffect(() => {
    fetchCompanies()
  }, [])

  const filteredCompanies = companies.filter((company) => {
    const term = searchTerm.toLowerCase()
    const matchesSearch =
      (company.name && company.name.toLowerCase().includes(term)) ||
      (company.number && company.number.toLowerCase().includes(term)) ||
      (company.director && company.director.toLowerCase().includes(term))

    if (!matchesSearch) return false

    if (activeTab === 'attention') {
      return company.status === 'Overdue' || company.status === 'Inactive'
    }
    if (activeTab === 'not-registered') {
      return company.status === 'Pending' || company.status === 'Draft'
    }
    return true
  })

  // Selection handlers
  const handleToggleSelect = (id) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]
    )
  }

  const handleSelectAll = () => {
    const visibleIds = filteredCompanies.map((c) => c.id).filter(Boolean)
    const allSelected = visibleIds.every((id) => selectedIds.includes(id))
    if (allSelected) {
      setSelectedIds((prev) => prev.filter((id) => !visibleIds.includes(id)))
    } else {
      setSelectedIds((prev) => Array.from(new Set([...prev, ...visibleIds])))
    }
  }

  const handleDeselectAll = () => {
    setSelectedIds([])
  }

  // Delete Handlers (optimistic + Undo)
  const handleConfirmDelete = () => {
    const idsToDelete = singleDeleteId ? [singleDeleteId] : [...selectedIds]
    if (!idsToDelete.length) return
    const idSet = new Set(idsToDelete)
    const snapshot = companies
    const removedCount = idsToDelete.length

    setDeleteConfirmOpen(false)
    setSingleDeleteId(null)
    setIsDeleting(false)
    setSelectedIds((prev) => prev.filter((id) => !idSet.has(id)))
    setCompanies((prev) => prev.filter((c) => !idSet.has(c.id)))

    toastUndoableDelete({
      message:
        removedCount === 1
          ? 'Company deleted'
          : `${removedCount} companies deleted`,
      description: 'Undo available for a few seconds',
      onUndo: () => setCompanies(snapshot),
      onCommit: async () => {
        const apiUrl = import.meta.env.VITE_API_URL || '/api'
        const token = localStorage.getItem('token')
        let res
        if (idsToDelete.length === 1) {
          res = await fetch(`${apiUrl}/admin/companies/${idsToDelete[0]}`, {
            method: 'DELETE',
            credentials: 'include',
            headers: {
              'Content-Type': 'application/json',
              ...(token ? { Authorization: `Bearer ${token}` } : {}),
            },
          })
        } else {
          res = await fetch(`${apiUrl}/admin/companies/bulk-delete`, {
            method: 'POST',
            credentials: 'include',
            headers: {
              'Content-Type': 'application/json',
              ...(token ? { Authorization: `Bearer ${token}` } : {}),
            },
            body: JSON.stringify({ company_ids: idsToDelete }),
          })
        }
        const data = await res.json().catch(() => ({}))
        if (!(res.ok && data.success !== false)) {
          throw new Error(data.message || 'Failed to delete companies')
        }
      },
    })
  }

  const isAllVisibleSelected =
    filteredCompanies.length > 0 &&
    filteredCompanies.every((c) => selectedIds.includes(c.id))

  return (
    <div className="flex flex-col gap-6 w-full">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold tracking-tight">Registered Companies</h2>
        </div>
        <div className="flex items-center gap-3">
          <Button
            variant="outline"
            size="icon"
            onClick={fetchCompanies}
            disabled={isLoading}
            title="Refresh list"
          >
            <IconRefresh className={`h-4 w-4 ${isLoading ? 'animate-spin' : ''}`} />
          </Button>
          <Button variant="outline" onClick={() => setIsWebfilingModalOpen(true)}>
            <IconUpload className="mr-2 h-4 w-4" />
            Import WebFiling
          </Button>
          <Button onClick={() => setIsAddModalOpen(true)}>
            <IconBuildingPlus className="mr-2 h-4 w-4" />
            Add Company
          </Button>
        </div>
      </div>


      {/* Stats/Tabs & Search */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        {/* Tabs */}
        <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full md:w-auto">
          <TabsList className="flex-wrap h-auto justify-start">
            <TabsTrigger value="all" className="py-2">
              All
              <span className="ml-2 bg-muted-foreground/20 px-1.5 py-0.5 rounded-full text-xs min-w-[20px] text-center inline-flex items-center justify-center">
                {isLoading ? <Skeleton className="h-3 w-4 rounded-xs" /> : companies.length}
              </span>
            </TabsTrigger>
            <TabsTrigger value="uk" className="py-2">
              UK Portfolio
              <span className="ml-2 bg-muted-foreground/20 px-1.5 py-0.5 rounded-full text-xs min-w-[20px] text-center inline-flex items-center justify-center">
                {isLoading ? <Skeleton className="h-3 w-4 rounded-xs" /> : companies.length}
              </span>
            </TabsTrigger>
            <TabsTrigger
              value="attention"
              className="py-2 data-[state=active]:bg-destructive/10 data-[state=active]:text-destructive text-destructive"
            >
              Attention
            </TabsTrigger>
            <TabsTrigger value="not-registered" className="py-2">
              Draft / Pending
            </TabsTrigger>
          </TabsList>
        </Tabs>

        {/* Search */}
        <div className="relative w-full md:w-auto shrink-0">
          <IconSearch className="absolute left-2.5 top-1.5 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Search name, number, director…"
            className="w-full md:w-[280px] pl-9"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      {/* Bulk Action Bar when items selected */}
      {selectedIds.length > 0 && (
        <Card className="animate-in animate-out p-2 fade-in slide-in-from-top-2  duration-200">
          <CardContent className="w-full p-0.5 flex flex-wrap items-center justify-between gap-4">
          <div className="flex items-center gap-3 text-xs">
            <div className="flex items-center gap-2">
              <Checkbox
                checked={isAllVisibleSelected}
                onCheckedChange={handleSelectAll}
                id="select-all-header"
              />
              <label htmlFor="select-all-header" className="cursor-pointer">
                {isAllVisibleSelected ? 'Deselect visible' : `Select all visible (${filteredCompanies.length})`}
              </label>
            </div>
            <span className="text-muted-foreground">•</span>
            <span className="text-primary font-medium">
              {selectedIds.length} {selectedIds.length === 1 ? 'company' : 'companies'} selected
            </span>
          </div>

          <div className="flex items-center gap-2">
            <Button variant="ghost" size="sm" onClick={handleDeselectAll} className="text-xs h-8">
              Clear selection
            </Button>
            <Button
              variant="destructive"
              size="sm"
              className="text-xs h-8"
              onClick={() => {
                setSingleDeleteId(null)
                setDeleteConfirmOpen(true)
              }}
            >
              <IconTrash className="mr-1.5 h-3.5 w-3.5" />
              Delete Selected ({selectedIds.length})
            </Button>
          </div>
          </CardContent>
        </Card>
      )}

      {/* Grid / Skeletons */}
      {isLoading ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-3 gap-4 pb-8">
          {Array.from({ length: 6 }).map((_, i) => (
            <Skeleton key={i} className="w-full h-[270px] rounded-xl" />
          ))}
        </div>
      ) : filteredCompanies.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-16 px-4 rounded-xl border border-dashed text-center bg-card/40 my-4">
          <div className="flex h-14 w-14 items-center justify-center rounded-full bg-muted/60 mb-3 text-muted-foreground">
            <IconSearch className="h-6 w-6" />
          </div>
          <h3 className="text-lg font-semibold tracking-tight">No companies found</h3>
          <p className="text-sm text-muted-foreground max-w-sm mt-1 mb-4">
            {searchTerm
              ? `No records found matching "${searchTerm}". Try searching by a different name or number.`
              : 'No registered company records available for the selected view.'}
          </p>
          {searchTerm && (
            <Button variant="outline" size="sm" onClick={() => setSearchTerm('')}>
              Clear Search
            </Button>
          )}
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-3 gap-4 pb-8">
          {filteredCompanies.map((company, i) => (
            <CompanyCard
              key={company.id || i}
              company={company}
              isSelected={selectedIds.includes(company.id)}
              onToggleSelect={handleToggleSelect}
              onRefresh={fetchCompanies}
              onDelete={(id) => {
                setSingleDeleteId(id)
                setDeleteConfirmOpen(true)
              }}
            />
          ))}
        </div>
      )}

      {/* Reusable Delete Confirmation Dialog */}
      <DeleteConfirmation
        isOpen={deleteConfirmOpen}
        onClose={() => {
          setDeleteConfirmOpen(false)
          setSingleDeleteId(null)
        }}
        onConfirm={handleConfirmDelete}
        isLoading={isDeleting}
        title={singleDeleteId ? "Delete Company" : "Delete Selected Companies"}
        description={
          singleDeleteId
            ? "Are you sure you want to permanently delete this company record?"
            : `Are you sure you want to permanently delete ${selectedIds.length} selected company records?`
        }
        confirmText={isDeleting ? "Deleting..." : singleDeleteId ? "Delete" : `Delete (${selectedIds.length})`}
      />

      <AddCompany
        isOpen={isAddModalOpen}
        onClose={() => {
          setIsAddModalOpen(false)
          fetchCompanies()
        }}
      />

      <ImportWebfilingModal
        isOpen={isWebfilingModalOpen}
        onClose={() => setIsWebfilingModalOpen(false)}
        onImportSuccess={() => {
          fetchCompanies()
        }}
      />
    </div>
  )
}

export default Companies

import React, { useState, useEffect } from 'react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import { Label } from '@/components/ui/label'
import { Button } from '@/components/ui/button'
import { Checkbox } from '@/components/ui/checkbox'
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group'
import { Select, SelectContent, SelectGroup, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Badge } from '@/components/ui/badge'
import { IconUpload, IconCheck, IconAlertCircle, IconLoader2, IconBuilding, IconInfoCircle } from '@tabler/icons-react'
import { toast } from 'sonner'
import { toastProcessing, toastDone, toastFail } from '@/lib/toastActions'
import ToastSave from '@/components/ToastSave'

export function ImportWebfilingModal({ isOpen, onClose, onImportSuccess }) {
  const [companyNumbers, setCompanyNumbers] = useState('')
  const [clientMode, setClientMode] = useState('existing')
  const [selectedClientId, setSelectedClientId] = useState('')
  const [newClientName, setNewClientName] = useState('')
  const [newClientEmail, setNewClientEmail] = useState('')
  const [updateExisting, setUpdateExisting] = useState(false)

  const [clients, setClients] = useState([])
  const [isLoadingClients, setIsLoadingClients] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [errorMsg, setErrorMsg] = useState('')
  const [importResults, setImportResults] = useState(null)
  const [showUnsavedToast, setShowUnsavedToast] = useState(false)
  const [toastSaveState, setToastSaveState] = useState('initial')

  const isDirty = Boolean(companyNumbers.trim() || newClientName.trim() || newClientEmail.trim())

  const handleAttemptClose = () => {
    if (isSubmitting) return
    if (isDirty && !importResults) {
      setShowUnsavedToast(true)
    } else {
      onClose()
    }
  }

  // Load clients for dropdown
  useEffect(() => {
    if (isOpen) {
      setErrorMsg('')
      setImportResults(null)
      loadClients()
    }
  }, [isOpen])

  const loadClients = async () => {
    setIsLoadingClients(true)
    try {
      const apiUrl = import.meta.env.VITE_API_URL || '/api'
      const token = localStorage.getItem('token')
      const res = await fetch(`${apiUrl}/admin/customers`, {
        credentials: 'include',
        headers: {
          'Content-Type': 'application/json',
          ...(token ? { Authorization: `Bearer ${token}` } : {})
        }
      })
      if (res.ok) {
        const json = await res.json()
        const list = json.customers || json.data?.customers || json.data?.clients || (Array.isArray(json.data) ? json.data : [])
        if (Array.isArray(list)) {
          setClients(list)
          if (list.length > 0 && !selectedClientId) {
            setSelectedClientId(String(list[0].id))
          }
        }
      }
    } catch (err) {
      console.error('Failed to load clients for WebFiling import:', err)
    } finally {
      setIsLoadingClients(false)
    }
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    setErrorMsg('')

    const cleanNumbers = companyNumbers.trim()
    if (!cleanNumbers) {
      setErrorMsg('Please paste at least one Companies House number.')
      return
    }

    if (clientMode === 'existing' && !selectedClientId) {
      setErrorMsg('Please select a client to assign these companies to.')
      return
    }

    if (clientMode === 'new') {
      if (!newClientName.trim() || !newClientEmail.trim()) {
        setErrorMsg('Please enter both name and email for the new client.')
        return
      }
    }

    setIsSubmitting(true)
    const toastId = toastProcessing('Importing from WebFiling…')
    try {
      const apiUrl = import.meta.env.VITE_API_URL || '/api'
      const token = localStorage.getItem('token')
      const payload = {
        company_numbers: cleanNumbers,
        client_mode: clientMode,
        update_existing: updateExisting,
        ...(clientMode === 'existing' ? { client_id: Number(selectedClientId) } : {
          new_client_full_name: newClientName.trim(),
          new_client_email: newClientEmail.trim()
        })
      }

      const res = await fetch(`${apiUrl}/admin/companies/import-webfiling`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(token ? { Authorization: `Bearer ${token}` } : {})
        },
        credentials: 'include',
        body: JSON.stringify(payload)
      })

      const json = await res.json()
      const data = json.data || json

      if (res.ok && (json.status === 'success' || json.success)) {
        setImportResults(data)
        toastDone(toastId, json.message || 'Successfully processed WebFiling import.')
        if (onImportSuccess) {
          onImportSuccess()
        }
      } else {
        const msg = json.message || json.error || 'Failed to import companies from WebFiling.'
        setErrorMsg(msg)
        toastFail(toastId, msg)
      }
    } catch (err) {
      const msg = 'Network error during WebFiling import: ' + err.message
      setErrorMsg(msg)
      toastFail(toastId, msg)
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleReset = () => {
    setCompanyNumbers('')
    setImportResults(null)
    setErrorMsg('')
    setNewClientName('')
    setNewClientEmail('')
  }

  return (
    <>
      <Dialog open={isOpen} onOpenChange={(open) => { if (!open) handleAttemptClose() }}>
