              <TooltipContent>View</TooltipContent>
            </Tooltip>

            <Tooltip>
              <TooltipTrigger className="inline-flex">
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  className="h-7 shrink-0 px-2.5 text-xs"
                  disabled={busy}
                  onClick={async () => {
                    try { await downloadDocument(d.id, d.name) }
                    catch { toast.error('Download failed') }
