              <div>
                <div className="font-semibold">{triageDoc.name || 'Document'}</div>
                <div className="text-xs text-muted-foreground mt-0.5">
                  {[triageDoc.category, triageDoc.file_type, triageDoc.file_size].filter(Boolean).join(' · ')}
