              <div className="grid grid-cols-2 gap-3">
                <div>
                  <div className="text-[11px] text-muted-foreground">Customer</div>
                  <div>{triageDoc.client_name || '—'} {triageDoc.user_id ? `(#${triageDoc.user_id})` : ''}</div>
