                  Reject / Quarantine
                </Button>
                <Button
                  variant="outline"
                  disabled={actingId === triageDoc.id}
                  onClick={() => {
                    setReassignForm({
                      client_id: triageDoc.user_id ? String(triageDoc.user_id) : '',
                      company_id: triageDoc.company_id ? String(triageDoc.company_id) : '',
