  const [viewOrderOpen, setViewOrderOpen] = useState(false)

  const handleOpenOrder = useCallback((orderId) => {
    setSelectedOrderId(orderId)
    setViewOrderOpen(true)
  }, [])

  const fetchOrders = useCallback(async (page = 1) => {
    setIsLoading(true)
    setLoadError(null)
    try {
      const qs = new URLSearchParams({ page: String(page), limit: '25' })
      if (search.trim()) qs.set('search', search.trim())
      if (statusFilter !== 'all') qs.set('status', statusFilter)
      if (productFilter !== 'all') qs.set('product', productFilter)
      if (companyFilter !== 'all') qs.set('company_id', companyFilter)
      if (paymentFilter !== 'all') qs.set('payment_status', paymentFilter)
      if (datePreset !== 'all') qs.set('date_preset', datePreset)
      if (clientType === 'B2B') {
        qs.set('client_type', 'B2B')
        if (b2bClientId !== 'all') qs.set('customer_id', b2bClientId)
      } else if (clientType === 'Customer') {
        qs.set('client_type', 'Customer')
      }

      const res = await apiRequest(`/admin/orders?${qs.toString()}`, { label: 'Orders' })
      if (!res.ok) {
        // Fallback to /orders if admin alias fails
        const res2 = await apiRequest(`/orders?${qs.toString()}`, { label: 'Orders' })
        if (!res2.ok) {
          setOrders([])
          setLoadError(res2.reason || res.reason)
          return
        }
        const data = res2.data?.data || res2.data || {}
        applyPayload(data, page)
        return
      }
      const data = res.data?.data || res.data || {}
      applyPayload(data, page)
    } catch (err) {
      setOrders([])
      setLoadError(err?.message || 'Unexpected error')
    } finally {
      setIsLoading(false)
    }
  }, [search, statusFilter, productFilter, companyFilter, paymentFilter, datePreset, clientType, b2bClientId])

  function applyPayload(data, page) {
    const list = data.orders || []
    setOrders(list)
    if (data.stats) setStats(data.stats)
    if (data.facets) setFacets(data.facets)
    if (data.pagination) setPagination(data.pagination)
    else setPagination((p) => ({ ...p, page, total: data.total || list.length }))
    if (list.length === 0) toastApiEmpty('Orders', getApiBase())
  }

  useEffect(() => {
    const t = setTimeout(() => fetchOrders(1), 200)
    return () => clearTimeout(t)
  }, [fetchOrders])

  const b2bCustomers = useMemo(
    () => (facets.customers || []).filter((c) => Number(c.is_b2b) === 1 || String(c.client_type || '').toUpperCase() === 'B2B'),
    [facets.customers]
  )

  const updateOrder = async (orderId, payload) => {
    setSavingId(orderId)
    const toastId = toastProcessing('Updating order…')
    try {
      const res = await apiRequest(`/orders/${orderId}`, {
        method: 'PUT',
        body: JSON.stringify(payload),
        label: 'Update order',
        silent: true,
      })
      if (res.ok) {
        toastDone(toastId, 'Order updated')
        fetchOrders(pagination.page || 1)
      } else {
        toastFail(toastId, res.reason || 'Failed to update order')
      }
    } finally {
      setSavingId(null)
    }
  }

  const handleDelete = (order) => {
    if (!window.confirm(`Cancel order ${order.order_number || order.id}?`)) return
    const victim = order
    const snapshot = orders
    setOrders((prev) => prev.filter((o) => o.id !== victim.id))

    toastUndoableDelete({
      message: `Order ${victim.order_number || victim.id} cancelled`,
      description: 'Undo available for a few seconds',
      onUndo: () => setOrders(snapshot),
      onCommit: async () => {
        const res = await apiRequest(`/orders/${victim.id}`, {
          method: 'DELETE',
          label: 'Cancel order',
          silent: true,
        })
        if (!res.ok) throw new Error(res.reason || 'Failed to cancel order')
      },
    })
  }

  const statCards = useMemo(() => [
    { title: 'Total Orders', value: String(stats.total_orders ?? 0), footerSubText: 'Matching filters' },
    { title: 'Pending', value: String(stats.pending ?? 0), footerSubText: 'Pending / verification' },
    { title: 'In Progress', value: String(stats.in_progress ?? 0), footerSubText: 'Processing + in progress' },
    { title: 'Completed', value: String(stats.completed ?? 0), footerSubText: 'Finished orders' },
    {
      title: 'Total Revenue',
      value: `£${Number(stats.revenue || 0).toFixed(2)}`,
      footerSubText: 'Excluding cancelled',
    },
  ], [stats])

  const columns = useMemo(() => [
    columnHelper.display({
      id: 'select',
      header: ({ table }) => (
        <Checkbox
          checked={table.getIsAllPageRowsSelected() || (table.getIsSomePageRowsSelected() && 'indeterminate')}
          onCheckedChange={(v) => table.toggleAllPageRowsSelected(!!v)}
          aria-label="Select all"
        />
      ),
      cell: ({ row }) => (
        <Checkbox
          checked={row.getIsSelected()}
          onCheckedChange={(v) => row.toggleSelected(!!v)}
          aria-label="Select row"
        />
      ),
      enableSorting: false,
      enableHiding: false,
    }),
    columnHelper.accessor('order_number', {
      header: 'Order #',
      cell: ({ row }) => (
        <Badge
          className="badge-sky rounded-full font-mono cursor-pointer hover:opacity-80 transition-opacity"
          onClick={() => handleOpenOrder(row.original.id)}
        >
          {formatOrderNumberDisplay(row.original.order_number)}
        </Badge>
      ),
    }),
    columnHelper.accessor('created_at', {
      header: 'Date',
      cell: ({ row }) => (
        <span className="text-xs text-muted-foreground">
          {row.original.created_at
            ? new Date(row.original.created_at).toLocaleDateString('en-GB', { day: '2-digit', month: '2-digit', year: '2-digit' })
            : '—'}
        </span>
      ),
    }),
    columnHelper.display({
      id: 'owner',
      header: 'Owner',
      cell: ({ row }) => {
        const o = row.original
        const name = o.owner_name || o.client_name || '—'
        const email = o.owner_form_email || o.client_email || '—'
        return (
          <div
            className="flex flex-col max-w-[160px] min-w-0 cursor-pointer hover:opacity-80"
            onClick={() => handleOpenOrder(o.id)}
          >
            <TruncatedTooltip text={name} className="block max-w-full truncate text-left font-medium text-sm cursor-pointer" />
            <TruncatedTooltip text={email} className="block max-w-full truncate text-left text-xs text-muted-foreground cursor-pointer" />
          </div>
        )
      },
    }),
    columnHelper.accessor('company_name', {
      header: 'Company',
      cell: ({ row }) => {
        const name = row.getValue('company_name') || '—'
        return (
          <TruncatedTooltip
            text={name}
            className="block max-w-[140px] truncate text-left text-xs cursor-default"
          />
        )
      },
    }),
    columnHelper.display({
      id: 'product',
      header: 'Product',
      cell: ({ row }) => (
        <ProductPills summary={row.original.products_summary || row.original.service_name} />
      ),
    }),
    columnHelper.display({
      id: 'price',
      header: 'Price',
      cell: ({ row }) => {
        const o = row.original
        const totalNum = Number(o.total || 0)
        return (
          <span className="text-xs font-semibold tabular-nums">
            £{totalNum.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </span>
        )
      },
    }),
    columnHelper.display({
      id: 'payment',
      header: 'Payment',
      cell: ({ row }) => {
        const o = row.original
        const current = o.payment_mode || ''
        return (
          <Select
            value={current || 'none'}
            onValueChange={(val) => updateOrder(o.id, { payment_mode: val === 'none' ? null : val })}
            disabled={savingId === o.id}
          >
            <SelectTrigger className="h-7 w-[88px] text-xs">
              <SelectValue placeholder="Select" />
            </SelectTrigger>
            <SelectContent className="overflow-hidden p-0">
              <SelectGroup className="p-1">
                <SelectItem value="none">Select</SelectItem>
                {PAYMENT_MODES.map((m) => (
                  <SelectItem key={m.value} value={m.value}>{m.label}</SelectItem>
                ))}
              </SelectGroup>
            </SelectContent>
          </Select>
        )
      },
    }),
    columnHelper.display({
      id: 'status',
      header: 'Status',
      cell: ({ row }) => {
        const o = row.original
        const pct = progressPercent(o)
        return (
          <Tooltip>
            <TooltipTrigger className="inline-flex">
              <Badge className={`${statusTone(o, pct)} tabular-nums cursor-pointer`} onClick={() => handleOpenOrder(o.id)}>
                {pct}%
              </Badge>
            </TooltipTrigger>
            <TooltipContent>{o.status || 'Pending'} · {pct}%</TooltipContent>
          </Tooltip>
        )
      },
    }),
    columnHelper.display({
      id: 'actions',
      header: 'Action',
      cell: ({ row }) => {
        const o = row.original
        return (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" size="icon" className="h-8 w-8 text-muted-foreground">
                <IconDotsVertical className="h-4 w-4" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end">
              <DropdownMenuItem onClick={() => handleOpenOrder(o.id)}>
                <IconFolderOpen className="w-4 h-4 mr-2" />
                Open order
              </DropdownMenuItem>
              <DropdownMenuItem
                className="text-destructive focus:text-destructive"
                onClick={() => handleDelete(o)}
              >
                <IconTrash className="w-4 h-4 mr-2" />
                Delete / Cancel
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        )
      },
    }),
  ], [savingId, handleOpenOrder])

  const tableFilterConfig = useMemo(() => [
    {
      key: 'company',
      placeholder: 'Company',
      allLabel: 'All Companies',
      value: companyFilter,
      onValueChange: setCompanyFilter,
      options: (facets.companies || []).map((c) => ({ label: c.name, value: String(c.id) })),
    },
    {
      key: 'status',
      placeholder: 'Status',
      allLabel: 'All Statuses',
      value: statusFilter,
      onValueChange: setStatusFilter,
      options: STATUS_OPTIONS.map((s) => ({ label: s, value: s })),
    },
    {
      key: 'product',
      placeholder: 'Product',
      allLabel: 'All Products',
      value: productFilter,
      onValueChange: setProductFilter,
      options: (facets.products || []).map((p) => ({ label: p, value: p })),
    },
    {
      key: 'payment',
      placeholder: 'Payment',
      allLabel: 'All Payments',
      value: paymentFilter,
      onValueChange: setPaymentFilter,
      options: [
        { label: 'Paid', value: 'Paid' },
        { label: 'Pending', value: 'Pending' },
        { label: 'Overdue', value: 'Overdue' },
        { label: 'Unpaid', value: 'Unpaid' },
      ],
    },
    {
      key: 'date',
      placeholder: 'Date',
      allLabel: 'All Dates',
      value: datePreset,
      onValueChange: setDatePreset,
      options: DATE_PRESETS.filter((d) => d.value !== 'all').map((d) => ({ label: d.label, value: d.value })),
    },
  ], [facets.companies, facets.products, companyFilter, statusFilter, productFilter, paymentFilter, datePreset])

  const clearFilters = () => {
    setSearch('')
    setStatusFilter('all')
    setProductFilter('all')
    setCompanyFilter('all')
    setPaymentFilter('all')
    setDatePreset('all')
    setB2bClientId('all')
  }

  return (
    <div className="flex flex-col gap-4 w-full pb-10">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-3">
        <div>
          <h2 className="text-2xl font-bold tracking-tight">Admin Orders Manager</h2>
        </div>
        <div className="flex gap-2 flex-wrap">
          <Button variant="outline" onClick={() => fetchOrders(pagination.page || 1)}>
            <IconRefresh className="mr-2 h-4 w-4" />
            Refresh
          </Button>
          <Button onClick={() => setCreateOpen(true)}>
            <IconPlus className="mr-2 h-4 w-4" />
            Create Order
          </Button>
          <Button variant="outline" onClick={() => setQuickCrmOpen(true)}>
            <IconFileInvoice className="mr-2 h-4 w-4" />
            Quick CRM Order
          </Button>
        </div>
      </div>

      <SectionCards stats={statCards} isLoading={isLoading} compact />

      <Tabs
        value={clientType === 'All' ? 'All' : clientType === 'Customer' ? 'Customer' : 'B2B'}
        onValueChange={(v) => {
          setClientType(v)
          setB2bClientId('all')
        }}
      >
        <TabsList>
          <TabsTrigger value="All" className="text-xs rounded-full data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
            All Orders
          </TabsTrigger>
          <TabsTrigger value="Customer" className="text-xs rounded-full data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
            Customers
          </TabsTrigger>
          <TabsTrigger value="B2B" className="text-xs rounded-full data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
            B2B Clients
          </TabsTrigger>
        </TabsList>
      </Tabs>

      {clientType === 'B2B' && (
        <div className="rounded-lg border bg-card p-3 space-y-2">
          <div className="text-sm font-semibold">Select a B2B client</div>
          <p className="text-xs text-muted-foreground">Open a B2B account first, then their orders appear below.</p>
          <Select value={b2bClientId} onValueChange={setB2bClientId}>
            <SelectTrigger className="max-w-md h-8 text-xs">
              <SelectValue placeholder="Choose B2B client" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All B2B clients</SelectItem>
              {b2bCustomers.map((c) => (
                <SelectItem key={c.id} value={String(c.id)}>
                  {c.full_name || c.email} {c.b2b_id ? `(${c.b2b_id})` : ''}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      )}

      <DataTable
        columns={columns}
        data={orders}
        filterConfig={tableFilterConfig}
        isLoading={isLoading}
        searchValue={search}
        onSearchChange={setSearch}
        searchPlaceholder="Search orders…"
        onClearFilters={clearFilters}
      />

      <div className="flex items-center justify-between gap-3 text-xs text-muted-foreground">
        <span>
          {pagination.total || 0} orders · page {pagination.page || 1} of {pagination.total_pages || 1}
        </span>
        <div className="flex gap-2">
          <Button
            variant="outline"
            size="sm"
            disabled={(pagination.page || 1) <= 1 || isLoading}
            onClick={() => fetchOrders((pagination.page || 1) - 1)}
          >
            Previous
          </Button>
          <Button
            variant="outline"
            size="sm"
            disabled={(pagination.page || 1) >= (pagination.total_pages || 1) || isLoading}
            onClick={() => fetchOrders((pagination.page || 1) + 1)}
          >
            Next
          </Button>
        </div>
      </div>

      <CreateOrderWizard
        open={createOpen}
        onClose={() => setCreateOpen(false)}
        onCreated={() => fetchOrders(1)}
      />
      <QuickCrmOrder
        open={quickCrmOpen}
        onClose={() => setQuickCrmOpen(false)}
        onCreated={() => fetchOrders(1)}
      />
      <ViewOrder
        orderId={selectedOrderId}
        isOpen={viewOrderOpen}
        onClose={() => {
          setViewOrderOpen(false)
          setSelectedOrderId(null)
        }}
        onOrderUpdated={() => fetchOrders(pagination.page || 1)}
      />
    </div>
  )
}

import React, { useCallback, useEffect, useMemo, useState } from "react"
import {
  Drawer,
  DrawerContent,
  DrawerDescription,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
} from "@/components/ui/drawer"
import { ScrollArea } from "@/components/ui/scroll-area"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { toast } from "sonner"
import { toastProcessing, toastDone, toastFail } from "@/lib/toastActions"
import { apiRequest } from "@/lib/api"
import ToastSave from "@/components/ToastSave"
import { IconLoader2, IconPlus, IconTrash } from "@tabler/icons-react"

const COMPANY_TYPES = [
  "Private Limited Company by Shares (LTD)",
  "Limited Liability Partnership (LLP)",
  "Public Limited Company (PLC)",
  "Company Limited by Guarantee",
  "Sole Trader / Business Partnership",
]

const SIC_CODES = [
  "62020 - Information technology consultancy activities",
  "70229 - Management consultancy activities other than financial management",
  "68209 - Letting and operating of own or leased real estate",
  "47910 - Retail sale via mail order houses or via Internet",
  "82990 - Other business support service activities n.e.c.",
  "Other",
]

const PAYMENT_CHANNELS = [
  "Website Checkout",
  "Bank Transfer",
  "Invoice",
  "Manual CRM",
  "Card Payment",
]

const INITIAL_STATUSES = [
  "Processing",
  "Pending Verification",
  "Pending",
  "In Progress",
  "Completed",
]

function unwrapList(res, keys = []) {
  const root = res?.data
  if (!root) return []
  if (Array.isArray(root)) return root
  if (Array.isArray(root.data)) return root.data
  for (const k of keys) {
    if (Array.isArray(root[k])) return root[k]
    if (root.data && Array.isArray(root.data[k])) return root.data[k]
  }
  return []
}

function newLine() {
  return {
    id: `line_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
    product_name: "",
    price: "",
  }
}

function Section({ title, children }) {
  return (
    <section className="rounded-xl border bg-muted/20 p-4 sm:p-5 space-y-4">
      <h4 className="text-sm font-bold text-foreground">{title}</h4>
      {children}
    </section>
  )
}

export default function QuickCrmOrder({ open, onClose, onCreated }) {
  const [error, setError] = useState("")
  const [submitting, setSubmitting] = useState(false)
  const [loadingClients, setLoadingClients] = useState(false)
  const [loadingCompanies, setLoadingCompanies] = useState(false)
  const [services, setServices] = useState([])

  const [clientMode, setClientMode] = useState("existing")
  const [clients, setClients] = useState([])
  const [clientId, setClientId] = useState("")
  const [newClientName, setNewClientName] = useState("")
  const [newClientEmail, setNewClientEmail] = useState("")

  const [companies, setCompanies] = useState([])
  const [companyId, setCompanyId] = useState("none")
  const [companyName, setCompanyName] = useState("")
  const [companyType, setCompanyType] = useState(COMPANY_TYPES[0])
  const [sicCode, setSicCode] = useState(SIC_CODES[0])
  const [companyEmail, setCompanyEmail] = useState("")
  const [companyPhone, setCompanyPhone] = useState("")
  const [regAddress, setRegAddress] = useState("")
  const [regCity, setRegCity] = useState("")
  const [regPostcode, setRegPostcode] = useState("")

  const [ownerName, setOwnerName] = useState("")
  const [directorPhone, setDirectorPhone] = useState("")
  const [directorNationality, setDirectorNationality] = useState("")
  const [directorResidence, setDirectorResidence] = useState("United Kingdom")

  const [lines, setLines] = useState([newLine()])
  const [paymentMode, setPaymentMode] = useState("Manual CRM")
  const [status, setStatus] = useState("Processing")
  const [notes, setNotes] = useState("")
  const [showUnsavedToast, setShowUnsavedToast] = useState(false)
  const [toastSaveState, setToastSaveState] = useState("initial")

  const isDirty = Boolean(
    clientId ||
    newClientName.trim() ||
    newClientEmail.trim() ||
    companyName.trim() ||
    (companyEmail.trim() && companyEmail !== clients.find((c) => String(c.id) === String(clientId))?.email) ||
    companyPhone.trim() ||
    regAddress.trim() ||
    ownerName.trim() ||
    lines.some((l) => l.product_name.trim() || l.price) ||
    notes.trim()
  )

  const total = useMemo(
    () =>
      lines.reduce((sum, line) => {
        const n = parseFloat(line.price)
        return sum + (Number.isFinite(n) && n > 0 ? n : 0)
      }, 0),
    [lines]
  )

  const resetForm = useCallback(() => {
    setError("")
    setClientMode("existing")
    setClientId("")
    setNewClientName("")
    setNewClientEmail("")
    setCompanies([])
    setCompanyId("none")
    setCompanyName("")
    setCompanyType(COMPANY_TYPES[0])
    setSicCode(SIC_CODES[0])
    setCompanyEmail("")
    setCompanyPhone("")
    setRegAddress("")
    setRegCity("")
    setRegPostcode("")
    setOwnerName("")
    setDirectorPhone("")
    setDirectorNationality("")
    setDirectorResidence("United Kingdom")
    setLines([newLine()])
    setPaymentMode("Manual CRM")
    setStatus("Processing")
    setNotes("")
  }, [])

  const loadClients = useCallback(async () => {
    setLoadingClients(true)
    try {
      const res = await apiRequest("/admin/customers?limit=500", {
        label: "Customers",
        silent: true,
      })
      setClients(unwrapList(res, ["customers", "clients", "users"]))
    } finally {
      setLoadingClients(false)
    }
  }, [])

  const loadServices = useCallback(async () => {
    let res = await apiRequest("/admin/services", { label: "Services", silent: true })
    let list = unwrapList(res, ["services", "products"])
    if (!list.length) {
      res = await apiRequest("/catalog/products", { label: "Catalog", silent: true })
      list = unwrapList(res, ["products", "services"])
    }
    setServices(list)
  }, [])

  const loadCompaniesForClient = useCallback(async (cid) => {
    setCompanies([])
    setCompanyId("none")
    if (!cid) return
    setLoadingCompanies(true)
    try {
      const res = await apiRequest(`/admin/companies?client_id=${cid}&limit=200`, {
        label: "Companies",
        silent: true,
      })
      const list = unwrapList(res, ["companies"])
      setCompanies(
        list.map((c) => ({
          id: c.id,
          name: c.name || c.company_name || "Company",
        }))
      )
    } finally {
      setLoadingCompanies(false)
    }
  }, [])

  useEffect(() => {
    if (!open) return
    resetForm()
    loadClients()
    loadServices()
  }, [open, resetForm, loadClients, loadServices])

  useEffect(() => {
    if (clientMode !== "existing" || !clientId) {
      setCompanies([])
      setCompanyId("none")
      return
    }
    const selected = clients.find((c) => String(c.id) === String(clientId))
    if (selected?.email) setCompanyEmail(selected.email)
    if (selected?.full_name && !ownerName) setOwnerName(selected.full_name)
    loadCompaniesForClient(clientId)
  }, [clientId, clientMode, clients, loadCompaniesForClient]) // eslint-disable-line react-hooks/exhaustive-deps

  const updateLine = (id, field, value) => {
    setLines((prev) =>
      prev.map((line) => {
        if (line.id !== id) return line
        const next = { ...line, [field]: value }
        if (field === "product_name") {
          const match = services.find((s) => s.name === value)
          if (match && match.price != null) next.price = String(match.price)
        }
        return next
      })
    )
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    setError("")

    const line_items = lines
      .map((l) => ({
        product_name: String(l.product_name || "").trim(),
        price: parseFloat(l.price) || 0,
      }))
      .filter((l) => l.product_name)

    if (!line_items.length) {
      setError("Please add at least one product or service.")
      return
    }
    if (clientMode === "existing" && !clientId) {
      setError("Please select a client.")
      return
    }
    if (clientMode === "new" && (!newClientName.trim() || !newClientEmail.trim())) {
      setError("Please enter the new client name and email.")
      return
    }
    if (!companyEmail.trim()) {
      setError("Please enter the company notification email.")
      return
    }

    const payload = {
      client_mode: clientMode,
      client_id: clientMode === "existing" ? clientId : undefined,
      new_client_full_name: clientMode === "new" ? newClientName.trim() : undefined,
      new_client_email: clientMode === "new" ? newClientEmail.trim() : undefined,
      company_id: companyId !== "none" ? companyId : "",
      company_name: companyName.trim(),
      company_type: companyType,
      sic_code: sicCode,
      company_email: companyEmail.trim(),
      company_phone: companyPhone.trim(),
      reg_office: [regAddress, regCity, regPostcode].map((s) => s.trim()).filter(Boolean).join(", "),
      registered_address_line1: regAddress.trim(),
      registered_city: regCity.trim(),
      registered_postcode: regPostcode.trim(),
      owner_name: ownerName.trim(),
      director_phone: directorPhone.trim(),
      director_nationality: directorNationality.trim(),
      director_residence: directorResidence.trim() || "United Kingdom",
      payment_mode: paymentMode,
      status,
      notes: notes.trim(),
      line_items,
    }

    setSubmitting(true)
    const toastId = toastProcessing("Creating order…")
    try {
      let res = await apiRequest("/admin/orders", {
        method: "POST",
        body: JSON.stringify(payload),
        label: "Create manual order",
        silent: true,
      })
      if (!res.ok) {
        res = await apiRequest("/orders", {
          method: "POST",
          body: JSON.stringify(payload),
          label: "Create manual order",
          silent: true,
        })
      }
      if (!res.ok) {
        setError(res.reason || "Could not create order.")
        toastFail(toastId, res.reason || "Could not create order.")
        return
      }
      const data = res.data?.data || res.data || {}
      const num = data.order_number || data.order?.order_number
      toastDone(toastId, res.data?.message || `Order ${num || ""} created successfully.`)
      onClose?.()
      onCreated?.(data)
    } finally {
      setSubmitting(false)
    }
  }

  const handleAttemptClose = () => {
    if (submitting) return
    if (isDirty) {
      setShowUnsavedToast(true)
    } else {
      onClose?.()
    }
  }

  return (
