function syncLocalUser(user) {
  if (!user) return
  try {
    const prev = JSON.parse(localStorage.getItem('user') || '{}')
    localStorage.setItem(
      'user',
      JSON.stringify({
        ...prev,
        ...user,
        name: user.full_name || user.name || prev.name,
        full_name: user.full_name || user.name || prev.full_name,
      })
    )
  } catch (_) {
    /* ignore */
  }
}

