              </div>
              <div className="space-y-2">
                <Label htmlFor="task-due">Due date</Label>
                <Input
                  id="task-due"
                  type="date"
                  value={taskForm.due_date}
                  onChange={(e) =>
                    setTaskForm((p) => ({ ...p, due_date: e.target.value }))
                  }
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label>Assignee</Label>
              <Select
                value={taskForm.assigned_staff_id || undefined}
                onValueChange={(val) =>
                  setTaskForm((p) => ({ ...p, assigned_staff_id: val }))
                }
              >
                <SelectTrigger className="w-full">
                  <SelectValue placeholder="Assign to…" />
                </SelectTrigger>
                <SelectContent>
                  {staff.map((s) => (
                    <SelectItem key={s.id} value={String(s.id)}>
                      {s.name} ({humanRole(s.role)})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <DialogFooter>
              <Button
                type="button"
                variant="outline"
                onClick={() => setTaskDialogOpen(false)}
                disabled={taskSaving}
              >
                Cancel
              </Button>
              <Button type="submit" disabled={taskSaving}>
                {taskSaving ? (
                  <IconLoader2 className="size-4 animate-spin" />
                ) : null}
                {editingTask ? 'Save changes' : 'Create task'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* Add Team Member */}
      <Dialog
        open={staffDialogOpen}
        onOpenChange={(open) => {
          if (!staffSaving) setStaffDialogOpen(open)
        }}
      >
        <DialogContent className="sm:max-w-[480px]">
          <DialogHeader>
            <DialogTitle>Add team member</DialogTitle>
            <DialogDescription>
              Create a staff account that can be assigned to tasks.
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={saveStaff} className="space-y-4">
            {staffError ? (
              <Alert variant="destructive">
                <IconAlertCircle className="size-4" />
                <AlertDescription>{staffError}</AlertDescription>
              </Alert>
            ) : null}

            <div className="space-y-2">
              <Label htmlFor="staff-name">
                Full name <span className="text-destructive">*</span>
              </Label>
              <Input
                id="staff-name"
                value={staffForm.full_name}
                onChange={(e) =>
                  setStaffForm((p) => ({ ...p, full_name: e.target.value }))
                }
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="staff-email">
                Email <span className="text-destructive">*</span>
              </Label>
              <Input
                id="staff-email"
                type="email"
                value={staffForm.email}
                onChange={(e) =>
                  setStaffForm((p) => ({ ...p, email: e.target.value }))
                }
                required
              />
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="staff-phone">Phone</Label>
                <Input
                  id="staff-phone"
                  value={staffForm.phone}
                  onChange={(e) =>
                    setStaffForm((p) => ({ ...p, phone: e.target.value }))
                  }
                />
              </div>
              <div className="space-y-2">
                <Label>Role</Label>
                <Select
                  value={staffForm.role}
                  onValueChange={(val) =>
                    setStaffForm((p) => ({ ...p, role: val }))
                  }
                >
                  <SelectTrigger className="w-full">
                    <SelectValue placeholder="Role" />
                  </SelectTrigger>
                  <SelectContent>
                    {STAFF_ROLES.map((r) => (
                      <SelectItem key={r} value={r}>
                        {humanRole(r)}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="space-y-2">
              <Label htmlFor="staff-password">
                Temporary password <span className="text-destructive">*</span>
              </Label>
              <Input
                id="staff-password"
                type="password"
                value={staffForm.password}
                onChange={(e) =>
                  setStaffForm((p) => ({ ...p, password: e.target.value }))
                }
                placeholder="Min. 10 characters"
                required
              />
            </div>

            <DialogFooter>
              <Button
                type="button"
                variant="outline"
                onClick={() => setStaffDialogOpen(false)}
                disabled={staffSaving}
              >
                Cancel
              </Button>
              <Button type="submit" disabled={staffSaving}>
                {staffSaving ? (
                  <IconLoader2 className="size-4 animate-spin" />
                ) : null}
                Add member
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      <DeleteConfirmation
        isOpen={!!taskToDelete}
        onClose={() => !isDeleting && setTaskToDelete(null)}
        onConfirm={confirmDeleteTask}
        isLoading={isDeleting}
        title="Delete task?"
        description={
          taskToDelete
            ? `“${taskToDelete.title}” will be permanently removed.`
            : ''
        }
      />
    </div>
  )
}

