                  />
                }
              >
                <IconX className="size-4" />
              </DrawerClose>
            </div>
          </header>

          {/* Messages */}
          <ScrollArea className="min-h-0 flex-1">
            <div className="flex flex-col gap-5 px-5 py-4 pb-6">
              {messages.length === 0 ? (
                <div className="flex min-h-[240px] flex-col items-center justify-center gap-3 text-center">
