import React, { createContext, useContext, useState, useEffect } from 'react';

const PrivacyContext = createContext({
  isPrivate: false,
  togglePrivacy: () => {},
  setPrivacy: () => {},
});

export const usePrivacy = () => useContext(PrivacyContext);

const LOOSE_CURRENCY_REGEX = /[£$€]\s?-?[\d,]+(\.\d+)?/i;

export function PrivacyProvider({ children }) {
  const [isPrivate, setIsPrivate] = useState(() => {
    try {
      return localStorage.getItem('crm_privacy_mode') === 'true';
    } catch {
      return false;
    }
  });

  const togglePrivacy = () => {
    setIsPrivate((prev) => {
      const next = !prev;
      try {
        localStorage.setItem('crm_privacy_mode', String(next));
      } catch {
        // ignore storage errors
      }
      return next;
    });
  };

  const setPrivacy = (val) => {
    setIsPrivate(val);
    try {
      localStorage.setItem('crm_privacy_mode', String(val));
    } catch {
      // ignore
    }
  };

  useEffect(() => {
    document.documentElement.classList.toggle('privacy-mode', isPrivate);

    const scanAndMarkCurrency = (root = document.body) => {
      if (!root) return;

      if (root.nodeType === Node.ELEMENT_NODE) {
        if (
          root.tagName === 'SCRIPT' ||
          root.tagName === 'STYLE' ||
          root.tagName === 'INPUT' ||
          root.tagName === 'TEXTAREA' ||
          root.classList.contains('no-privacy-mask')
        ) {
          return;
        }
      }

      const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null, false);
      let node;
      while ((node = walker.nextNode())) {
        const text = node.textContent?.trim();
        if (text && LOOSE_CURRENCY_REGEX.test(text)) {
          const parent = node.parentElement;
          if (
            parent &&
            parent.tagName !== 'SCRIPT' &&
            parent.tagName !== 'STYLE' &&
            parent.tagName !== 'INPUT' &&
            parent.tagName !== 'TEXTAREA' &&
            !parent.classList.contains('no-privacy-mask')
          ) {
            parent.classList.add('privacy-currency-mask');
          }
        }
      }
    };

    scanAndMarkCurrency();

    const observer = new MutationObserver((mutations) => {
      for (const mutation of mutations) {
        if (mutation.type === 'childList') {
          mutation.addedNodes.forEach((node) => {
            if (node.nodeType === Node.ELEMENT_NODE) {
              scanAndMarkCurrency(node);
            } else if (
              node.nodeType === Node.TEXT_NODE &&
              LOOSE_CURRENCY_REGEX.test(node.textContent || '')
            ) {
              const parent = node.parentElement;
              if (
                parent &&
                parent.tagName !== 'SCRIPT' &&
                parent.tagName !== 'STYLE' &&
                parent.tagName !== 'INPUT' &&
                parent.tagName !== 'TEXTAREA' &&
                !parent.classList.contains('no-privacy-mask')
              ) {
                parent.classList.add('privacy-currency-mask');
              }
            }
          });
        } else if (mutation.type === 'characterData') {
          if (LOOSE_CURRENCY_REGEX.test(mutation.target.textContent || '')) {
            const parent = mutation.target.parentElement;
            if (
              parent &&
              parent.tagName !== 'SCRIPT' &&
              parent.tagName !== 'STYLE' &&
              parent.tagName !== 'INPUT' &&
              parent.tagName !== 'TEXTAREA' &&
              !parent.classList.contains('no-privacy-mask')
            ) {
              parent.classList.add('privacy-currency-mask');
            }
          }
        }
      }
    });

    observer.observe(document.body, {
      childList: true,
      subtree: true,
      characterData: true,
    });

    return () => observer.disconnect();
  }, [isPrivate]);

  return (
    <PrivacyContext.Provider value={{ isPrivate, togglePrivacy, setPrivacy }}>
      {children}
    </PrivacyContext.Provider>
  );
}

import { createContext, useContext, useEffect, useState } from "react"

const initialState = {
  theme: "system",
  setTheme: () => null,
}

const ThemeProviderContext = createContext(initialState)

export function ThemeProvider({
  children,
  defaultTheme = "system",
  storageKey = "vite-ui-theme",
  ...props
}) {
  const [theme, setTheme] = useState(
    () => localStorage.getItem(storageKey) || defaultTheme
  )

  useEffect(() => {
    const root = window.document.documentElement

    root.classList.remove("light", "dark")

    if (theme === "system") {
      const systemTheme = window.matchMedia("(prefers-color-scheme: dark)")
        .matches
        ? "dark"
        : "light"

      root.classList.add(systemTheme)
      return
    }

    root.classList.add(theme)
  }, [theme])

  const value = {
    theme,
    setTheme: (newTheme) => {
      localStorage.setItem(storageKey, newTheme)
      setTheme(newTheme)
    },
  }

  return (
    <ThemeProviderContext.Provider {...props} value={value}>
      {children}
    </ThemeProviderContext.Provider>
  )
}

export const useTheme = () => {
  const context = useContext(ThemeProviderContext)

  if (context === undefined)
    throw new Error("useTheme must be used within a ThemeProvider")

  return context
}

import * as React from "react"

const MOBILE_BREAKPOINT = 768

export function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState(undefined)

  React.useEffect(() => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`)
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    }
    mql.addEventListener("change", onChange)
    setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    return () => mql.removeEventListener("change", onChange)
  }, [])

  return !!isMobile
}

/**
 * Shared API helpers — clear toast reasons when backend data fails to load.
 */
import { toast } from "@/components/ui/toast"

export function getApiBase() {
  return String(import.meta.env.VITE_API_URL || "/api").replace(/\/$/, "")
}

export function authHeaders(extra = {}) {
  const token = localStorage.getItem("token")
  return {
    "Content-Type": "application/json",
    ...(token ? { Authorization: `Bearer ${token}` } : {}),
    ...extra,
  }
}

function networkReason(err, apiBase) {
  const msg = String(err?.message || err || "")
  if (/Failed to fetch|NetworkError|Load failed|fetch/i.test(msg)) {
    return (
      `Cannot reach API at ${apiBase}. ` +
      `Check if backend is running and CORS allows requests.`
    )
  }
  return msg || "Unknown network error"
}

function httpReason(res, data, apiBase, rawText) {
  const serverMsg =
    (data && (data.error || data.message || data.detail)) ||
    (typeof rawText === "string" && rawText && !rawText.trim().startsWith("<")
      ? rawText.slice(0, 160)
      : null)

  if (res.status === 401) {
    return (
      serverMsg ||
      "Session expired or missing token. Please log in again."
    )
  }
  if (res.status === 403) {
    return serverMsg || "Access denied. Your role cannot access this resource."
  }
  if (res.status === 404) {
    return (
      serverMsg ||
      `Resource not found (404) on ${apiBase}.`
    )
  }
  if (res.status === 502 || res.status === 503 || res.status === 504) {
    return (
      serverMsg ||
      `Server/Gateway unavailable (${res.status}). Server might be restarting.`
    )
  }
  if (res.status >= 500) {
    return serverMsg || `Internal Server Error (${res.status}).`
  }
  if (typeof rawText === "string" && rawText.includes("<!doctype html")) {
    return (
      `Got HTML page instead of JSON from ${apiBase}. Check VITE_API_URL.`
    )
  }
  return serverMsg || `Request failed with HTTP status ${res.status}.`
}

/**
 * Show a clear, readable error toast.
 */
export function toastApiError({ title, reason, status, url } = {}) {
  const desc = [reason, status && status !== 0 ? `(Status: ${status})` : null]
    .filter(Boolean)
    .join(" ")
  toast.error(title || "API Request Failed", {
    description: desc || "Unable to complete request. Please try again.",
    duration: 5000,
  })
}

/**
 * Soft info when API succeeded but list is empty.
 */
export function toastApiEmpty(label, apiBase) {
  toast.info(`${label}: No records found`, {
    description: `API responded successfully, but there is no data to display.`,
    duration: 4000,
  })
}

/**
 * fetch wrapper with auth + structured result + optional toast on failure.
 *
 * @returns {{ ok: boolean, status: number, data: any, url: string, reason?: string, title?: string }}
 */
export async function apiRequest(path, options = {}) {
  const {
    silent = false,
    label = "Data",
    headers: extraHeaders,
    ...fetchOpts
  } = options

  const base = getApiBase()
  const url = path.startsWith("http")
    ? path
    : `${base}${path.startsWith("/") ? path : `/${path}`}`

  let res
  try {
    res = await fetch(url, {
      credentials: "include",
      ...fetchOpts,
      headers: {
        ...authHeaders(),
        ...(extraHeaders || {}),
      },
    })
  } catch (err) {
    const info = {
      ok: false,
      status: 0,
      data: null,
      url,
      title: `${label} failed to load`,
      reason: networkReason(err, base),
    }
    if (!silent) toastApiError(info)
    return info
  }

  const rawText = await res.text()
  let data = null
  try {
    data = rawText ? JSON.parse(rawText) : null
  } catch {
    data = null
  }

  if (!res.ok) {
    const info = {
      ok: false,
      status: res.status,
      data,
      url,
      title: `${label} failed to load`,
      reason: httpReason(res, data, base, rawText),
    }
    if (!silent) toastApiError(info)
    return info
  }

  if (data && typeof data === "object" && data.success === false) {
    const info = {
      ok: false,
      status: res.status,
      data,
      url,
      title: `${label} failed to load`,
      reason: data.error || data.message || "API returned success: false",
    }
    if (!silent) toastApiError(info)
    return info
  }

  // HTML success page? still wrong host
  if (typeof rawText === "string" && rawText.trim().toLowerCase().startsWith("<!doctype")) {
    const info = {
      ok: false,
      status: res.status,
      data: null,
      url,
      title: `${label} failed to load`,
      reason: httpReason(res, null, base, rawText),
    }
    if (!silent) toastApiError(info)
    return info
  }

  return { ok: true, status: res.status, data, url }
}

import * as XLSX from 'xlsx';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';

/**
 * Export data to Excel (.xlsx)
 * @param {Array} data - Array of objects to export
 * @param {String} fileName - Name of the file
 */
export const exportToExcel = (data, fileName = 'Export') => {
    try {
        const worksheet = XLSX.utils.json_to_sheet(data);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Data');

        // Generate buffer
        const excelBuffer = XLSX.write(workbook, { bookType: 'xlsx', type: 'array' });
        const blob = new Blob([excelBuffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });

        // Download
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `${fileName}.xlsx`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        return { fileName: `${fileName}.xlsx` };
    } catch (error) {
        console.error("Excel Export Error:", error);
        throw error;
    }
};

/**
 * Export data to CSV
 * @param {Array} data - Array of objects to export
 * @param {String} fileName - Name of the file
 */
export const exportToCSV = (data, fileName = 'Export') => {
    try {
        const worksheet = XLSX.utils.json_to_sheet(data);
        const csvOutput = XLSX.utils.sheet_to_csv(worksheet);
        const blob = new Blob([csvOutput], { type: 'text/csv;charset=utf-8;' });

        const link = document.createElement('a');
        if (link.download !== undefined) {
            const url = URL.createObjectURL(blob);
            link.href = url;
            link.download = `${fileName}.csv`;
            link.style.visibility = 'hidden';
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            return { fileName: `${fileName}.csv` };
        } else {
            throw new Error("Download not supported by this browser");
        }
    } catch (error) {
        console.error("CSV Export Error:", error);
        throw error;
    }
};

/**
 * Export data to PDF
 * @param {Array} data - Array of objects to export
 * @param {Array} columns - Column definitions for the table
 * @param {String} title - Title of the PDF document
 * @param {String} fileName - Name of the file
 */
export const exportToPDF = (data, columns, title = 'Report', fileName = 'Report') => {
    try {
        const doc = new jsPDF();

        // Add title
        doc.setFontSize(18);
        doc.text(title, 14, 22);
        doc.setFontSize(11);
        doc.setTextColor(100);
        doc.text(`Generated on: ${new Date().toLocaleString()}`, 14, 30);

        // Filter headers and keys
        const headers = columns.map(col => col.header);
        const keys = columns.map(col => col.key);

        const body = data.map(item => {
            return keys.map(key => item[key] !== undefined && item[key] !== null ? String(item[key]) : 'N/A');
        });

        autoTable(doc, {
            startY: 35,
            head: [headers],
            body: body,
            theme: 'striped',
            headStyles: { fillColor: [79, 70, 229] }, // indigo-600
            styles: { fontSize: 9 },
            didDrawPage: (data) => {
                // Add page number footer if needed
            }
        });

        doc.save(`${fileName}.pdf`);
        return { fileName: `${fileName}.pdf` };
    } catch (error) {
        console.error("PDF Export Error:", error);
        throw error;
    }
};

